// Üretilen dosya: tool/ozgun/uret.py. Tarih · Birinci Dünya Savaşı ve savaşlar arası dönem (dünya) (orta).
const ozHistory9Orta = <(String, String, List<String>, String)>[
  ('Almanya\'nın 1890\'da Rusya ile olan gizli antlaşmayı yenilememesi uzun vadede hangi sonucu doğurmuştur?', 'Rusya\'nın Fransa ile ittifak kurarak Almanya\'yı iki cepheyle karşı karşıya bırakması', ['İngiltere\'nin Almanya ile resmî bir askerî ittifaka girerek Fransa\'yı tamamen yalnız bırakması', 'Avusturya-Macaristan\'ın Üçlü İttifak\'tan çekilmesi', 'Rusya\'nın Balkanlardan tamamen elini çekmesi'], 'Yalnız kalan Rusya 1894\'te Fransa ile ittifak yaptı; böylece Bismarck\'ın kaçındığı iki cepheli savaş riski Almanya için gerçek bir tehlikeye dönüştü.'),
  ('İngiltere ile Rusya\'nın 1907\'de nüfuz alanlarını belirleyerek uzlaştığı anlaşmada aşağıdaki bölgelerden hangisi ele alınmamıştır?', 'Kore', ['İran', 'Afganistan', 'Tibet'], '1907 İngiliz-Rus Anlaşması İran\'ı nüfuz alanlarına bölmüş, Afganistan ve Tibet konusunda da uzlaşı sağlamıştır; Kore bu anlaşmanın konusu değildir.'),
  ('İngiltere\'nin 19. yüzyılın büyük bölümünde Avrupa\'daki kalıcı ittifaklardan uzak durma politikası hangi adla anılır?', 'Şanlı yalnızlık', ['Denge siyaseti', 'Kapı açık politikası', 'Yatıştırma'], 'Şanlı yalnızlık anlayışı 1902 İngiliz-Japon ittifakı ve ardından 1904 ile 1907 anlaşmalarıyla terk edildi.'),
  ('II. Wilhelm\'in 1905\'te Tanca\'yı ziyaret ederek Fas\'ın bağımsızlığını desteklediğini açıklamasıyla başlayan bunalım hangi konferansla sonuçlandırılmıştır?', 'Algeciras Konferansı', ['Berlin Kongresi', 'Lahey Konferansı', 'Londra Konferansı'], '1906 Algeciras Konferansı\'nda Fransa\'nın Fas\'taki özel konumu büyük ölçüde onaylandı; Almanya\'yı yalnız Avusturya-Macaristan destekledi.'),
  ('1906 Algeciras Konferansı\'nın Almanya açısından sonucu nasıl değerlendirilir?', 'Almanya\'nın yalnızlaştığı ve İngiliz-Fransız yakınlaşmasının güçlendiği bir diplomatik yenilgi', ['Almanya\'nın Fas\'ı himayesine alıp Akdeniz\'de kalıcı bir deniz üssü elde ettiği bir diplomatik zafer', 'Rusya\'yı İtilaf bloğundan kopardığı bir başarı', 'İtalya\'yı ittifaka sıkıca bağladığı bir uzlaşma'], 'Almanya İngiliz-Fransız anlaşmasını sınamak isterken tersine iki ülkeyi birbirine yaklaştırdı ve kendisi yalnız kaldı.'),
  ('Avusturya-Macaristan\'ın 1908\'de Bosna-Hersek\'i ilhak etmesine Rusya\'nın etkili bir karşılık verememesinin sonucu aşağıdakilerden hangisidir?', 'Rusya\'nın bir dahaki Balkan bunalımında geri adım atmamaya kararlı hâle gelmesi', ['Rusya\'nın Sırbistan\'la ilişkilerini kesmesi', 'Rusya\'nın Avusturya ile uzlaşarak Üçlü İttifak\'a katılması ve Sırbistan\'ı yalnız bırakması', 'Avusturya\'nın Balkanlardan çekilmesi'], 'Bosna bunalımında Almanya\'nın desteklediği Avusturya karşısında aşağılanan Rusya, 1914\'te Sırbistan\'ı yalnız bırakmama yönünde daha sert bir tavır aldı.'),
  ('Rusya\'nın Balkanlardaki Slav halkları, özellikle Sırbistan\'ı koruma iddiasını besleyen ideoloji hangisidir?', 'Pan-Slavizm', ['Pan-Germenizm', 'Siyonizm', 'Pan-Helenizm'], 'Pan-Slavizm, Slav halklarının birliğini ve Rusya\'nın bu halkların koruyucusu olmasını savunuyordu; bu durum Rusya\'yı Avusturya ile karşı karşıya getirdi.'),
  ('1906\'da denize indirilen ve yalnız büyük çaplı toplarla donatılmasıyla önceki bütün zırhlıları eskimiş duruma düşüren İngiliz savaş gemisi hangisidir?', 'HMS Dreadnought', ['HMS Hood', 'HMS Victory', 'HMS Warspite'], 'Dreadnought\'un çıkışı yeni bir sınıf başlattı; bu durum İngiltere\'nin eski üstünlüğünü sıfırladığı için Alman-İngiliz deniz yarışını kızıştırdı.'),
  ('1898 ve 1900 donanma yasalarıyla güçlü bir Alman savaş filosu kurulmasının mimarı olan amiral kimdir?', 'Alfred von Tirpitz', ['Reinhard Scheer', 'Franz von Hipper', 'Maximilian von Spee'], 'Tirpitz\'in donanma yasaları İngiltere\'yi tedirgin etti ve iki ülke arasındaki deniz silahlanma yarışını başlattı.'),
  ('Saraybosna suikastını düzenleyen gençlerle bağlantılı olan ve Sırp subaylarınca kurulan gizli örgüt hangi adla bilinir?', 'Kara El', ['Genç Bosna', 'Narodna Odbrana', 'Mavri Mira'], '\'Birlik ya da Ölüm\' diye de bilinen Kara El, Sırp ordusu içindeki milliyetçi subayların örgütüydü; suikastçılara silah ve eğitim sağladı.'),
  ('Almanya\'nın Temmuz 1914 başında Avusturya-Macaristan\'a Sırbistan\'a karşı ne yaparsa yapsın destek vereceğini bildirmesi tarihte hangi adla anılır?', 'Açık çek', ['Emsal kararı', 'Ems telgrafı', 'Tam yetki belgesi'], '5-6 Temmuz 1914\'teki koşulsuz destek güvencesi \'açık çek\' olarak anılır ve Avusturya\'yı sert bir ültimatoma cesaretlendirdi.'),
  ('Avusturya-Macaristan Sırbistan\'a hangi gün savaş ilan ederek Temmuz Krizi\'ni silahlı çatışmaya dönüştürmüştür?', '28 Temmuz 1914', ['28 Haziran 1914', '4 Ağustos 1914', '1 Ağustos 1914'], 'Suikasttan tam bir ay sonra, 28 Temmuz 1914\'te Avusturya-Macaristan Sırbistan\'a savaş ilan etti; ittifaklar zinciri birkaç gün içinde devreye girdi.'),
  ('İngiltere\'nin 4 Ağustos 1914\'te Almanya\'ya savaş ilan etmesinin doğrudan gerekçesi aşağıdakilerden hangisidir?', 'Almanya\'nın tarafsızlığı güvence altındaki Belçika\'yı işgal etmesi', ['Almanya\'nın savaş ilanı yapmadan İngiliz kıyı limanlarını donanmasıyla bombalaması', 'Almanya\'nın Fransa\'ya ültimatom vermesi', 'Almanya\'nın Lusitania\'yı batırması'], 'Belçika\'nın tarafsızlığı 1839 Londra Antlaşması ile güvence altındaydı; Alman ordusunun Belçika\'ya girmesi İngiltere\'nin savaşa katılma gerekçesi oldu.'),
  ('İtalya Üçlü İttifak üyesi olduğu hâlde 1914\'te tarafsız kalmıştır. İtalya\'nın bu tutumuna dayanak olarak ileri sürdüğü gerekçe hangisidir?', 'İttifakın savunma amaçlı olduğu, Avusturya\'nın ise saldıran taraf olduğu', ['İtalya\'nın o sırada Habeşistan\'la savaşta olduğu ve ordusunun Afrika\'da bulunduğu', 'İttifak antlaşmasının 1913\'te sona erdiği', 'Papa\'nın İtalya\'nın savaşa girmesini yasakladığı'], 'İtalya, ittifakın yalnız saldırıya uğrayan üyeyi korumayı öngördüğünü ve Avusturya\'nın kendisine danışmadan saldırdığını öne sürdü.'),
  ('Temmuz 1914 bunalımında savaşın kısa sürede yerel bir çatışmadan genel bir Avrupa savaşına dönüşmesinin temel nedeni nedir?', 'Büyük güçlerin birbirine bağlayıcı ittifaklar ve katı seferberlik planlarıyla bağlı olması', ['Avrupa\'da tek bir merkezî hükümetin bulunmaması', 'Sırbistan\'ın bütün büyük güçlere savaş ilan etmesi', 'ABD\'nin savaşa en baştan katılması'], 'Avusturya-Sırbistan çatışması Rusya\'yı, Rusya Almanya\'yı, Almanya Fransa\'yı ve Belçika üzerinden İngiltere\'yi zincirleme biçimde savaşa çekti.'),
  ('1914 Ağustosu\'nda Almanya\'nın Belçika\'ya girişinde ilk büyük direnişle karşılaştığı ve ağır kuşatma toplarıyla düşürdüğü kale kenti hangisidir?', 'Liège', ['Brugge', 'Gent', 'Anvers limanı'], 'Liège kaleleri Alman ilerleyişini birkaç gün geciktirdi; Almanlar kaleleri dev obüslerle düşürdü.'),
  ('Marne yenilgisinin ardından Alman genelkurmay başkanlığından alınan ve yerine Erich von Falkenhayn getirilen komutan kimdir?', 'Helmuth von Moltke', ['Alfred von Schlieffen', 'Paul von Hindenburg', 'Erich Ludendorff'], 'Genç Moltke, Schlieffen Planı\'nın başarısızlığının sorumlusu sayıldı ve Eylül 1914\'te görevden alındı.'),
  ('Marne\'den sonra iki tarafın birbirinin kuzey kanadını çevirmeye çalışırken Kuzey Denizi kıyısına kadar uzanan yarışına ne ad verilir?', 'Denize Koşu', ['Kanal Atılımı', 'Kanat Savaşları', 'Kuzey Harekâtı'], 'Karşılıklı kuşatma girişimleri sonuçsuz kalınca cephe Kuzey Denizi\'nden İsviçre sınırına kadar uzanan kesintisiz bir siper hattına dönüştü.'),
  ('1914 sonbaharında Batı Cephesi\'nde hareket savaşının yerini siper savaşına bırakmasının temel nedeni nedir?', 'Savunma silahlarının ateş gücünün açık arazide taarruzu aşırı pahalı kılması', ['Kış koşullarının ve yağmurların bütün ordu hareketlerini aylarca durdurması', 'İki tarafın da cephaneyi tamamen tüketmesi', 'Barış görüşmeleri için ateşkes yapılması'], 'Makineli tüfek, hızlı ateşli top ve tel örgü karşısında piyade taarruzu çok kanlı hâle geldi; ordular korunmak için toprağa gömüldü.'),
  ('Ağustos 1914\'te Doğu Prusya\'da Samsonov komutasındaki Rus ordusunun kuşatılıp imha edildiği muharebe hangisidir?', 'Tannenberg Muharebesi', ['Lodz Muharebesi', 'Gumbinnen Muharebesi', 'Lemberg Muharebesi'], 'Tannenberg\'de Rus İkinci Ordusu çember içinde yok edildi; Samsonov yenilginin ardından intihar etti.'),
  ('Tannenberg zaferiyle Almanya\'da ulusal kahramana dönüşen ve savaşın sonraki yıllarında ordunun fiilî yönetimini üstlenen komutan ikilisi hangisidir?', 'Hindenburg ve Ludendorff', ['Moltke ve Falkenhayn', 'Mackensen ve Seeckt', 'Tirpitz ve Scheer'], 'Hindenburg ile Ludendorff, 1916\'dan itibaren Yüksek Komuta\'yı yönetti ve Almanya\'da adeta askerî bir diktatörlük kurdu.'),
  ('Çar II. Nikolay\'ın 1915\'te ordunun başkomutanlığını bizzat üstlenmesi monarşi için neden zararlı olmuştur?', 'Askerî yenilgilerin doğrudan çarın şahsına yüklenmesine yol açması', ['Çarın Petrograd\'da sürekli bulunmasını gerektirmesi', 'Ordunun Almanya ile ayrı barış imzalamasına neden olması', 'Duma\'nın yetkilerinin artırılmasını ve anayasal monarşiye geçişi zorunlu kılması'], 'Cepheye giden çar yenilgilerin sorumlusu olarak görülmeye başladı; başkentte ise yönetim Çariçe ve çevresine kaldı, bu da monarşinin itibarını sarstı.'),
  ('Haziran 1916\'da Avusturya-Macaristan ordusuna ağır kayıplar verdiren ve savaşın en başarılı Rus taarruzu sayılan harekât hangisidir?', 'Brusilov Taarruzu', ['Kerenski Taarruzu', 'Naroç Gölü Taarruzu', 'Tannenberg Harekâtı'], 'General Brusilov\'un geniş bir cephede aynı anda yaptığı taarruz Avusturya-Macaristan\'ı çöküşün eşiğine getirdi.'),
  ('Temmuz 1917\'de Rus Geçici Hükümeti\'nin başlattığı son büyük taarruzun başarısız olmasının iç siyasete etkisi hangisidir?', 'Ordunun dağılmasını hızlandırıp Bolşeviklere zemin hazırlaması', ['Çarın yeniden tahta çıkarılması', 'Geçici Hükümet\'in halk desteğini artırıp Kurucu Meclis seçimlerini erkene alması', 'Rusya\'nın Almanya\'ya savaş tazminatı ödemesi'], 'Kerenski Taarruzu\'nun çöküşü firarları artırdı, Geçici Hükümet\'in itibarını yitirmesine ve savaş karşıtı Bolşeviklerin güçlenmesine yol açtı.'),
  ('1915 sonbaharında Sırbistan\'ın işgal edilmesinin ardından Sırp ordusunun kalıntıları hangi yolla kurtarılmıştır?', 'Arnavutluk dağlarını aşıp Adriyatik kıyısından Korfu\'ya taşınarak', ['Romanya ve Ukrayna üzerinden demiryoluyla Rusya\'ya geçip orada yeniden örgütlenerek', 'Bulgaristan\'a sığınarak', 'Karadeniz yoluyla Odessa\'ya giderek'], 'Kış ortasında Arnavutluk üzerinden yapılan geri çekilmede binlerce kişi öldü; sağ kalanlar İtilaf gemileriyle Korfu\'ya taşındı, sonra Selanik Cephesi\'ne katıldı.'),
  ('Bulgaristan I. Dünya Savaşı\'na hangi tarafta ve hangi yıl girmiştir?', 'Merkez Devletleri safında, 1915', ['İtilaf Devletleri safında, 1916', 'Merkez Devletleri safında, 1914', 'İtilaf Devletleri safında, 1915'], 'Balkan Savaşları\'nda kaybettiği Makedonya\'yı geri almak isteyen Bulgaristan Ekim 1915\'te Merkez Devletleri\'ne katılarak Sırbistan\'a saldırdı.'),
  ('İtilaf Devletleri\'nin 1915\'ten itibaren Yunanistan\'daki bir liman kentini üs edinerek açtığı Balkan cephesi hangi adla anılır?', 'Selanik Cephesi', ['Kavala Cephesi', 'Pire Cephesi', 'Dedeağaç Cephesi'], 'Selanik Cephesi uzun süre durağan kaldı; Eylül 1918\'de başlayan taarruz Bulgaristan\'ı ateşkese zorladı.'),
  ('Alman genelkurmay başkanı Falkenhayn\'ın 1916\'da Verdun\'a saldırırken izlediği strateji en iyi nasıl özetlenir?', 'Fransa\'yı simgesel bir kenti savunmaya zorlayıp ordusunu kan kaybıyla tüketmek', ['Paris\'e giden yolu açarak başkenti hızla ele geçirmek', 'İngiliz ordusunu Manş kıyısında denizden kuşatarak teslim olmaya zorlamak', 'Rus cephesine birlik kaydırmak için batıyı sakinleştirmek'], 'Falkenhayn, Fransızların Verdun\'dan geri çekilemeyeceğini ve burada ağır kayıplar vereceğini hesaplamıştı; ancak Alman ordusu da benzer ölçüde kan kaybetti.'),
  ('Pétain\'in Verdun\'da birlikleri kısa sürelerle cepheye gönderip sürekli değiştirmesi hangi sonucu doğurmuştur?', 'Fransız ordusunun çok büyük bir bölümünün Verdun\'dan geçerek bu deneyimi paylaşması', ['Verdun\'un yalnız sömürge birliklerince savunulması', 'Cephedeki asker sayısının yarıya düşmesi', 'Verdun\'daki birliklerin hiç değiştirilmeden aynı kişilerle savunulması'], 'Dönüşüm sistemi birliklerin tamamen tükenmesini önledi; bu yüzden Verdun, Fransız ordusunun ortak belleğinde ulusal bir sınav hâline geldi.'),
  ('Somme Muharebesi\'nin ilk günü olan 1 Temmuz 1916 İngiliz ordusu tarihi açısından neden ayrı bir yere sahiptir?', 'İngiliz ordusunun tek günde verdiği en ağır kayıpları yaşadığı gün olması', ['İngiliz ordusunun ilk kez Fransız komutasına girdiği gün olması', 'İngilizlerin Batı Cephesi\'nde ilk kez zehirli gazı büyük ölçekte denedikleri gün olması', 'Alman hatlarının tamamen yarıldığı tek gün olması'], 'İlk gün İngilizler yaklaşık 57 bin kayıp verdi, bunların yaklaşık 19 bini öldü; bu, İngiliz ordusu tarihindeki en kanlı gündür.'),
  ('İngiltere\'de aynı kasaba ya da iş yerinden gönüllülerin birlikte yazılıp aynı birlikte savaştığı \'Pals\' (Arkadaş) taburlarının Somme\'daki ağır kayıplardan sonra ortaya çıkan acı sonucu nedir?', 'Bazı kasabaların bir günde genç erkeklerinin önemli bir bölümünü yitirmesi', ['Gönüllülüğün tamamen yasaklanıp yerine yalnızca paralı askerlik sisteminin getirilmesi', 'Taburların komutanlarının yargılanması', 'Bu birliklerin cepheden tamamen çekilmesi'], 'Aynı yerden gelen arkadaşlar birlikte savaştığı için birliğin yok olması, tek bir topluluğun tüm kuşağını vurdu; sonradan birlikler karışık kurulmaya başlandı.'),
  ('Somme Muharebesi\'nde İngiliz kuvvetlerine komuta eden general kimdir?', 'Douglas Haig', ['John French', 'Herbert Plumer', 'Edmund Allenby'], 'Haig, Aralık 1915\'te John French\'in yerine geçti ve savaşın sonuna kadar İngiliz Sefer Kuvveti\'nin başında kaldı.'),
  ('Somme Muharebesi\'nin Temmuz-Kasım 1916 arasında süren dört buçuk ayın sonunda vardığı sonuç nasıl değerlendirilir?', 'Yüz binlerce kayba karşılık yalnızca birkaç kilometrelik bir ilerleme sağlandı', ['Alman cephesi çöktü ve Belçika kurtarıldı', 'İngilizler Ren Nehri\'ne ulaştı', 'Almanya\'nın ağır kayıplar karşısında barış önerisinde bulunmak zorunda kalması sağlandı'], 'Taraflar toplamda bir milyonu aşan kayıp verdi; İtilaf kuvvetleri en fazla on kilometre kadar ilerleyebildi. Muharebe yıpratma savaşının simgesi oldu.'),
  ('Nisan 1917\'de Chemin des Dames sırtlarında başlayan ve hızlı bir zafer vaat ettiği hâlde başarısız olan Fransız taarruzu hangi komutanın adıyla anılır?', 'Nivelle Taarruzu', ['Joffre Taarruzu', 'Foch Taarruzu', 'Mangin Taarruzu'], 'General Nivelle, 48 saatte yarma sözü vermişti; ağır kayıplarla biten taarruz onun görevden alınmasına yol açtı.'),
  ('1917 Mayıs-Haziran aylarında Fransız ordusunda yaşanan toplu itaatsizlik hareketlerinin temel nedeni nedir?', 'Askerlerin sonuçsuz ve kanlı taarruzlara yeniden gönderilmeyi reddetmesi', ['Bolşeviklerin Fransız ordusunu ele geçirmesi', 'Askerlerin Bolşevik örneğini izleyerek Almanya ile ayrı bir barış yapılmasını istemesi', 'Ordunun maaşlarının tamamen kesilmesi'], 'İsyancılar çoğunlukla savunmayı sürdürmeyi kabul ediyor ama anlamsız taarruzlara karşı çıkıyordu; izinler, beslenme ve dinlenme koşulları da şikâyet konusuydu.'),
  ('1917\'deki Fransız ordu isyanlarının ardından başa geçen Pétain\'in düzeni yeniden sağlamak için başvurduğu yol hangisidir?', 'Koşulları iyileştirip büyük taarruzları ABD kuvvetleri ve tanklar gelene kadar durdurmak', ['Bütün isyancı birlikleri dağıtıp sömürge askerleriyle yer değiştirmek', 'Almanya\'ya İsviçre aracılığıyla gizli bir ateşkes önerip savaşı kısa yoldan bitirmek', 'Orduyu Paris\'e çekip başkenti savunmak'], 'Pétain sınırlı sayıda idam cezasının yanında izinleri artırdı, iaşeyi düzeltti ve \'Amerikalıları ve tankları bekliyorum\' anlayışıyla savunmaya ağırlık verdi.'),
  ('Nisan 1917\'de Arras taarruzu sırasında Kanada Kolordusu\'nun dört tümeninin birlikte savaşarak ele geçirdiği ve Kanada ulusal kimliğinde simgeleşen sırt hangisidir?', 'Vimy Sırtı', ['Messines Sırtı', 'Aubers Sırtı', 'Pilckem Sırtı'], 'Vimy Sırtı\'nın alınması Kanada\'da ulusal bir dönüm noktası sayılır; bölgede bugün büyük bir Kanada anıtı bulunur.'),
  ('1917 sonbaharında yağmur ve çamur içinde geçen, Üçüncü Ypres diye de bilinen ve çok ağır kayıplara karşı az kazanç sağlayan muharebe hangi köyün adıyla anılır?', 'Passchendaele', ['Langemarck', 'Poelkapelle', 'Zonnebeke'], 'Temmuz-Kasım 1917 arasında süren muharebe, dövülmüş arazinin bataklığa dönmesiyle siper savaşının dehşetinin simgesi oldu.'),
  ('Kasım 1917\'deki Cambrai Muharebesi\'ni askerlik tarihi açısından önemli kılan özellik nedir?', 'Tankların ilk kez yüzlercesinin bir arada, kitlesel biçimde kullanılması', ['Uçakların ilk kez bomba atması', 'Zehirli gazın ilk kez kullanılması', 'Paraşütlü birliklerin ilk kez indirilmesi'], 'Cambrai\'de yaklaşık dört yüz tank uzun bir topçu hazırlığı olmadan sürpriz taarruz yaptı; ilk gün başarılı olsa da kazanımlar Alman karşı taarruzuyla büyük ölçüde geri alındı.'),
  ('Nisan 1915\'te İkinci Ypres Muharebesi\'nde Almanların Batı Cephesi\'nde büyük ölçekte ilk kez kullandığı zehirli gaz hangisidir?', 'Klor gazı', ['Hardal gazı', 'Sinir gazı', 'Göz yaşartıcı gaz'], 'Klor bulutu Fransız sömürge birliklerinin tuttuğu kesimde büyük bir gedik açtı; ancak Almanlar bu fırsatı değerlendirecek yedeklere sahip değildi.'),
  ('I. Dünya Savaşı\'nda piyadenin önünde adım adım ilerleyen topçu ateşiyle düşmanın başını siperde tutmayı amaçlayan tekniğe ne ad verilir?', 'Sürünen baraj ateşi', ['Kuşatma ateşi', 'Havan yaylımı', 'Karşı batarya ateşi'], 'Sürünen barajda topçu ateşi belirli aralıklarla ileri kaydırılır, piyade hemen arkasından ilerlerdi; başarı topçu ile piyadenin sıkı zamanlamasına bağlıydı.'),
  ('Siperlerde uzun süre ıslak ve soğuk ortamda kalan askerlerin ayaklarında görülen, kangrene kadar ilerleyebilen hastalığa ne ad verilir?', 'Siper ayağı', ['Siper humması', 'Kum ayağı', 'Çamur kangreni'], 'Islak çorapla günlerce durmak ayak dokusunu bozuyordu; kuru çorap değişimi ve ayakların yağlanması önlem olarak zorunlu kılındı.'),
  ('I. Dünya Savaşı\'nda ağır bombardımana maruz kalan askerlerde görülen titreme, konuşamama ve bellek kaybı gibi belirtiler o dönemde hangi adla tanımlanmıştır?', 'Mermi şoku', ['Siper ateşi', 'Gaz zehirlenmesi', 'Cephe tifosu'], 'Başta patlamaların fiziksel etkisine bağlanan bu durumun zamanla ruhsal travma olduğu anlaşıldı; bugünkü travma sonrası stres bozukluğu kavramının öncülerindendir.'),
  ('Ludendorff\'un Mart 1918\'de Batı Cephesi\'nde büyük bir taarruz başlatmak için acele etmesinin temel nedeni nedir?', 'ABD kuvvetleri cepheye çok sayıda ulaşmadan sonuç almak istemesi', ['Fransa\'nın barış istediğine dair gizli haber alması', 'Avusturya\'nın savaştan çekileceğini açıklaması', 'İngiltere\'nin bütün ordusunu Fransa\'dan çekip Orta Doğu cephesine göndermesi'], 'Rusya\'nın savaştan çıkmasıyla doğudan birlik aktaran Almanya, Amerikan askerlerinin dengeyi değiştirmesinden önce kesin zafer arıyordu.'),
  ('Almanların 1918 Bahar Taarruzu\'nun 21 Mart\'ta başlayan ilk ve en büyük aşaması hangi kod adla bilinir?', 'Michael Harekâtı', ['Barbarossa Harekâtı', 'Alberich Harekâtı', 'Gneisenau Harekâtı'], '\'Kaiserschlacht\' de denen taarruzun ilk aşaması Michael, İngiliz Beşinci Ordusu\'nu büyük ölçüde geri attı ama kesin yarma sağlayamadı.'),
  ('Mart 1918\'deki Alman taarruzunun yarattığı bunalım İtilaf Devletleri\'nde hangi kararın alınmasına yol açmıştır?', 'Müttefik ordularının Foch komutasında birleştirilmesi', ['İngiliz ordusunun Fransa\'dan çekilmesi', 'ABD\'nin müttefiklerinden habersiz olarak Almanya ile ayrı bir barış görüşmesi başlatması', 'Paris\'in açık şehir ilan edilmesi'], 'Doullens toplantısında Foch\'a koordinasyon görevi verildi; kısa süre sonra Batı Cephesi\'ndeki müttefik ordularının başkomutanı oldu.'),
  ('Ludendorff\'un \'Alman ordusunun kara günü\' olarak nitelediği 8 Ağustos 1918 hangi muharebenin ilk günüdür?', 'Amiens Muharebesi', ['Cambrai Muharebesi', 'Somme Muharebesi', 'Meuse-Argonne Muharebesi'], 'Amiens\'te tank, uçak ve piyadenin eş güdümlü saldırısı karşısında çok sayıda Alman askeri teslim oldu; bu, Alman ordusunun moralinin çöktüğünü gösterdi.'),
  ('Ağustos-Kasım 1918 arasında İtilaf ordularının Batı Cephesi boyunca peş peşe yaptığı ve savaşı bitiren taarruzlar dizisi hangi adla bilinir?', 'Yüz Gün Taarruzu', ['Bahar Taarruzu', 'Büyük Yarma', 'Son Saldırı Harekâtı'], 'Amiens ile başlayan Yüz Gün Taarruzu, Hindenburg Hattı\'nın aşılmasıyla Almanya\'yı ateşkes istemeye zorladı.'),
  ('Almanya\'nın Kasım 1918 ateşkesi görüşmelerinde heyetine başkanlık eden ve 1921\'de sağcı milliyetçilerce öldürülen siyasetçi kimdir?', 'Matthias Erzberger', ['Walther Rathenau', 'Friedrich Ebert', 'Gustav Stresemann'], 'Erzberger, ateşkesi imzaladığı için milliyetçilerin hedefi oldu ve 1921\'de bir suikastta öldürüldü.'),
  ('İtalya\'nın 1915\'te İtilaf safında savaşa girmesini sağlayan ve ona Avusturya topraklarından pay vaat eden gizli antlaşma hangisidir?', 'Londra Antlaşması', ['Rapallo Antlaşması', 'Saint-Jean-de-Maurienne Antlaşması', 'Uşi Antlaşması'], 'Nisan 1915 Londra Antlaşması İtalya\'ya Trentino, Güney Tirol, Trieste, İstirya ve Dalmaçya\'nın bir bölümünü vaat ediyordu.'),
  ('İtalyan ordusunun 1915-1917 arasında Avusturya\'ya karşı on bir kez sonuçsuz taarruz düzenlediği nehir hangisidir?', 'Isonzo', ['Piave', 'Po', 'Adige'], 'Isonzo boyunca dağlık arazide yapılan saldırılar çok kanlı geçti ve yalnızca sınırlı kazanımlar sağladı; on ikinci muharebe ise Caporetto yenilgisi oldu.'),
  ('Ekim 1917\'de Alman ve Avusturya birliklerinin İtalyan cephesini yararak İtalyan ordusunu yüz kilometreden fazla geri çekilmeye zorladığı muharebe hangisidir?', 'Caporetto Muharebesi', ['Vittorio Veneto Muharebesi', 'Asiago Muharebesi', 'Solferino Muharebesi'], 'Caporetto\'da İtalyanlar yüz binlerce esir verdi; ordu Piave Nehri\'nde ancak durabildi.'),
  ('İtalyan ordusunun Ekim-Kasım 1918\'de Avusturya-Macaristan ordusunu dağıttığı ve İtalya cephesindeki savaşı bitiren muharebe hangisidir?', 'Vittorio Veneto Muharebesi', ['Custoza Muharebesi', 'Caporetto Muharebesi', 'Isonzo\'nun On İkinci Muharebesi'], 'Vittorio Veneto\'dan sonra Avusturya-Macaristan 3 Kasım 1918\'de Villa Giusti Ateşkesi\'ni imzaladı.'),
  ('Ernest Hemingway\'in \'Silahlara Veda\' romanının arka planını İtalya cephesindeki hangi olay oluşturur?', 'Caporetto bozgunu ve ardından gelen geri çekilme', ['Verdun kuşatması ve Kutsal Yol', 'Tannenberg\'deki Rus yenilgisi', 'Gelibolu çıkarması ve İtilaf kuvvetlerinin yarımadadan geri çekilmesi'], 'Romanın kahramanı İtalyan ordusunda ambulans subayı olan bir Amerikalıdır; Caporetto\'daki geri çekilme romanın merkezî bölümünü oluşturur.'),
  ('I. Dünya Savaşı\'nda İngiltere\'nin Almanya\'ya uyguladığı deniz ablukasının uzun vadeli etkisi hangisidir?', 'Almanya\'da ciddi gıda kıtlığına yol açarak ev cephesini çökertmesi', ['Almanya\'nın bütün sömürgelerini hemen kaybetmesi', 'Alman donanmasının savaşın ilk yılında Kuzey Denizi\'nde tamamen batırılması', 'ABD\'nin Almanya safında savaşa girmesi'], 'Abluka Almanya\'nın ithalatını büyük ölçüde kesti; özellikle 1916-1917 kışından sonra açlık ve yoksulluk halkın direncini kırdı.'),
  ('1917\'de İngiltere\'nin denizaltı kayıplarını belirgin biçimde azaltmasını sağlayan önlem hangisidir?', 'Ticaret gemilerinin savaş gemisi korumasında konvoylar hâlinde yüzdürülmesi', ['Bütün ticaret gemilerinin gündüz limanda bekleyip yalnız gece karanlığında yol alması', 'Kuzey Denizi\'nin tamamen kapatılması', 'Ticaret gemilerinin tarafsız bayrak taşıması'], 'Konvoy sistemi denizaltıların hedef bulmasını zorlaştırdı ve eşlik eden gemilerin karşı saldırısına olanak verdi; kayıplar hızla düştü.'),
  ('1916 Jutland Deniz Savaşı\'nda İngilizler daha fazla gemi kaybettiği hâlde savaşın stratejik sonucunun İngiltere lehine olduğu söylenir. Bunun gerekçesi nedir?', 'Alman ana filosunun sonrasında açık denize çıkıp ablukayı kırma girişiminden vazgeçmesi', ['İngilizlerin savaştan hemen sonra Alman kıyılarına büyük bir çıkarma harekâtı yapması', 'Almanya\'nın bütün denizaltılarını yitirmesi', 'Alman amiralinin esir alınması'], 'Jutland\'dan sonra Alman yüzey filosu büyük ölçüde limanda kaldı; Almanya deniz savaşını denizaltılara yükledi ve İngiliz ablukası sürdü.'),
  ('Ateşkesten sonra İngiltere\'nin Scapa Flow limanında tutulan Alman donanmasının Haziran 1919\'da başına gelen olay hangisidir?', 'Kendi subaylarınca kasten batırılması', ['İngiltere\'ye satılması', 'Fransa ile ABD arasında paylaştırılması', 'Almanya\'ya geri gönderilmesi'], 'Amiral von Reuter, gemilerin İtilaf\'a teslim edilmemesi için 21 Haziran 1919\'da filonun batırılmasını emretti.'),
  ('I. Dünya Savaşı\'nda 1915\'ten itibaren İngiltere\'ye gece bombalama akınları düzenleyen Alman hava gemileri hangi adla anılır?', 'Zeplin', ['Gotha', 'Taube', 'Albatros'], 'Hidrojenle dolu dev zeplinler Londra\'ya kadar ulaştı; sivillerin hedef alınması savaşın cephe gerisini de kapsadığını gösterdi. Gotha ise 1917\'de kullanılan ağır bombardıman uçağıdır.'),
  ('Kırmızıya boyalı uçağıyla tanınan, savaşın en çok düşürme kaydeden pilotu sayılan ve Nisan 1918\'de vurularak ölen Alman pilot kimdir?', 'Manfred von Richthofen', ['Oswald Boelcke', 'Max Immelmann', 'Ernst Udet'], '\'Kızıl Baron\' diye anılan Richthofen\'e seksen hava zaferi atfedilir.'),
  ('Nisan 1918\'de İngiliz Kraliyet Uçan Kolordusu ile Kraliyet Deniz Hava Servisi\'nin birleştirilmesiyle kurulan ve dünyanın ilk bağımsız hava kuvveti sayılan kuruluş hangisidir?', 'Kraliyet Hava Kuvvetleri', ['Kraliyet Ordu Havacılığı', 'İngiliz Hava Filosu Komutanlığı', 'İmparatorluk Uçan Birliği'], 'RAF 1 Nisan 1918\'de kara ve deniz kuvvetlerinden bağımsız bir silah olarak kuruldu.'),
  ('I. Dünya Savaşı\'nın başında uçakların ordular için ilk ve en önemli görevi hangisiydi?', 'Keşif ve topçu ateşinin yönlendirilmesi', ['Düşman başkentlerini stratejik olarak bombalamak', 'Paraşütçü birlikleri cephe gerisine indirmek', 'Ağır yük ve mühimmatı cepheye taşımak'], 'Erken savaş uçakları silahsız gözetleme araçlarıydı; düşman hareketlerini izliyor ve topçu ateşini düzeltiyordu. Avcı ve bombardıman rolleri sonradan gelişti.'),
  ('Bütün ekonominin, sanayinin ve nüfusun savaş amacına seferber edildiği, sivillerle askerler arasındaki ayrımın bulanıklaştığı savaş türüne ne ad verilir?', 'Topyekûn savaş', ['Sınırlı savaş', 'Gerilla savaşı', 'Vekâlet savaşı'], 'I. Dünya Savaşı\'nda devletler üretimi, gıdayı, iş gücünü ve kamuoyunu yönettiği için savaş topyekûn bir nitelik kazandı.'),
  ('İngiltere\'de Ağustos 1914\'te kabul edilen ve hükümete sansür, el koyma ve üretimi yönlendirme gibi geniş yetkiler veren yasa hangisidir?', 'Krallığın Savunması Yasası', ['Haklar Bildirgesi', 'Askerlik Hizmeti Yasası', 'Olağanüstü Hâl ve Seferberlik Kararnamesi'], 'DORA ile hükümet gazeteleri denetledi, fabrikalara el koydu, pub saatlerini kısıtladı; devletin günlük hayata müdahalesi büyük ölçüde arttı.'),
  ('İngiltere\'de cephane fabrikalarında TNT ile çalışan kadın işçilere derilerinin sararması nedeniyle hangi lakap takılmıştır?', 'Kanaryalar', ['Sarı Melekler', 'Altın Kızlar', 'Limonlar'], 'TNT\'ye uzun süre maruz kalmak deriyi sarıya boyuyordu; bu işçiler sağlık riskine karşın savaş üretiminde kritik rol oynadı.'),
  ('Savaş yıllarında kadınların fabrikalarda, ulaşımda ve tarımda erkeklerin yerini alması savaş sonrasında hangi gelişmeyi hızlandırmıştır?', 'Birçok ülkede kadınlara oy hakkı tanınmasını', ['Kadınların askerî akademilere zorunlu alınmasını', 'Kadınların bütün işlerden çıkarılmasını yasaklayan uluslararası antlaşmayı', 'Kadınların yalnız ev işlerine yönlendirilmesini'], 'Kadınların savaş çabasındaki katkısı, İngiltere, Almanya ve ABD gibi ülkelerde 1918-1920 arasında oy hakkı reformlarına güçlü bir gerekçe oldu.'),
  ('Savaşın başında Almanya\'daki siyasi partilerin hükümeti desteklemek için aralarındaki çekişmeleri askıya almasına verilen ad hangisidir?', 'Burgfrieden', ['Kulturkampf', 'Lebensraum', 'Gleichschaltung'], 'Burgfrieden (kale barışı), Sosyal Demokratların da savaş kredilerine oy vermesiyle sağlandı; Fransa\'daki karşılığı \'Kutsal Birlik\' (Union sacrée) idi.'),
  ('İngiltere\'de 1915\'teki \'Mermi Bunalımı\'nın siyasi sonucu aşağıdakilerden hangisidir?', 'Koalisyon hükümeti kurulması ve Lloyd George\'un Cephane Bakanı olması', ['Başbakan Asquith\'in görevden alınıp yerine bir askerî kurulun yönetime getirilmesi', 'Bütün cephane üretiminin ABD\'ye devredilmesi', 'Lord Kitchener\'in başbakanlığa getirilmesi'], 'Cephede top mermisi sıkıntısının basına yansıması Liberal hükümeti koalisyona zorladı; yeni kurulan Cephane Bakanlığı\'nın başına Lloyd George getirildi.'),
  ('Almanların Ağustos 1914\'te Belçika\'da sivillere yönelik misillemeleri ve Leuven Üniversitesi kütüphanesini yakmaları İtilaf propagandasında nasıl kullanılmıştır?', 'Almanya\'yı uygarlık karşıtı bir saldırgan olarak göstermek için', ['Belçika\'nın tarafsızlığını sorgulamak için', 'Belçika\'nın savaş öncesindeki tarafsızlık politikasının samimiyetini sorgulamak için', 'İngiltere\'nin savaşa girmesine karşı çıkmak için'], '\'Belçika\'ya tecavüz\' söylemi, tarafsız ABD kamuoyunda da Almanya aleyhine güçlü bir etki yarattı.'),
  ('Kasım 1917\'de Fransa başbakanlığına getirilen, savaşı sonuna kadar kararlılıkla sürdürmesi nedeniyle \'Kaplan\' lakabıyla anılan siyasetçi kimdir?', 'Georges Clemenceau', ['Raymond Poincaré', 'Aristide Briand', 'Paul Painlevé'], 'Clemenceau bozgunculuğa karşı sert önlemler alarak Fransız kamuoyunu zafere kadar savaşmaya kilitledi.'),
  ('Woodrow Wilson\'ın 1916 başkanlık seçimini kazanmasında kullanılan \'Bizi savaştan uzak tuttu\' sloganı ABD kamuoyunun hangi eğilimini gösterir?', 'Avrupa savaşına katılmaya isteksizliğini', ['Almanya\'yla ittifak arzusunu', 'Meksika\'yı işgal etme isteğini', 'Japonya\'ya karşı Pasifik\'te kapsamlı bir savaş hazırlığına girişilmesini'], 'Wilson yeniden seçildikten birkaç ay sonra, sınırsız denizaltı savaşı ve Zimmermann Telgrafı nedeniyle Nisan 1917\'de savaş ilanı istemek zorunda kaldı.'),
  ('Avrupa\'ya gönderilen Amerikan Sefer Kuvvetleri\'nin komutanı kimdir?', 'John J. Pershing', ['Douglas MacArthur', 'George C. Marshall', 'Dwight Eisenhower'], 'Pershing, Amerikan askerlerinin müttefik birliklerine dağıtılmasına direnerek ayrı bir Amerikan ordusu olarak savaşmasını sağladı.'),
  ('Wilson\'ın Ocak 1918\'de açıkladığı 14 Madde\'nin ilk maddesi uluslararası ilişkilerde hangi ilkeyi öngörür?', 'Gizli antlaşmaların sona erip açık diplomasiye geçilmesi', ['Denizlerde savaşta ve barışta bütün ülkelere serbest dolaşım hakkı tanınması', 'Ekonomik engellerin olabildiğince kaldırılması', 'Ulusal silahlanmanın en alt düzeye indirilmesi'], 'İlk madde \'açıkça varılmış açık barış antlaşmaları\' ilkesidir; seçeneklerdeki öteki ilkeler sırasıyla ikinci, üçüncü ve dördüncü maddelerdir.'),
  ('Wilson İlkeleri\'nin son maddesinde önerilen ve sonradan Milletler Cemiyeti olarak hayata geçen fikir hangisidir?', 'Ulusların bağımsızlığını güvenceye alacak genel bir devletler birliği', ['Avrupa devletlerinin ortak bir orduda birleşmesi', 'Sömürgelerin ABD yönetimine devredilmesi', 'Dünya ticaretinin altına bağlı ortak tek bir para birimiyle yürütülmesi'], 'On dördüncü madde, büyük küçük bütün devletlerin siyasi bağımsızlığını ve toprak bütünlüğünü karşılıklı güvenceye alacak bir uluslar birliği öngörüyordu.'),
  ('Doğu Afrika\'da çok daha kalabalık İngiliz kuvvetlerine karşı gerilla savaşı yürüten ve ateşkesten sonra, Kasım 1918\'in sonlarında yenilmeden silah bırakan Alman komutan kimdir?', 'Paul von Lettow-Vorbeck', ['Erwin Rommel', 'Otto Liman von Sanders', 'Colmar von der Goltz'], 'Lettow-Vorbeck küçük bir Alman ve Afrikalı asker grubuyla dört yıl boyunca büyük İtilaf kuvvetlerini oyaladı.'),
  ('Alman Güneybatı Afrikası 1915\'te hangi ülkenin kuvvetlerince ele geçirilmiştir?', 'Güney Afrika Birliği', ['Portekiz', 'Belçika', 'Fransa'], 'Louis Botha komutasındaki Güney Afrika kuvvetleri bugünkü Namibya\'yı ele geçirdi; bölge savaştan sonra Güney Afrika\'nın manda yönetimine verildi.'),
  ('Japonya\'nın 1914\'te Almanya\'ya savaş ilan etmesinin asıl amacı aşağıdakilerden hangisidir?', 'Almanya\'nın Çin ve Pasifik\'teki topraklarını ele geçirerek nüfuzunu genişletmek', ['Avrupa\'daki Batı Cephesi\'ne İngiltere\'yi desteklemek için büyük bir kara ordusu göndermek', 'Rusya\'nın Sibirya\'daki topraklarını savunmak', 'ABD\'nin Pasifik\'teki üslerine saldırmak'], 'Japonya, İngiliz ittifakını gerekçe göstererek Çin\'deki Tsingtao üssünü ve Ekvator\'un kuzeyindeki Alman Pasifik adalarını ele geçirdi.'),
  ('Japon ve İngiliz kuvvetlerinin Kasım 1914\'te kuşatarak ele geçirdiği, Almanya\'nın Çin\'deki Shandong Yarımadası\'nda bulunan deniz üssü hangisidir?', 'Tsingtao', ['Port Arthur', 'Hong Kong', 'Şanghay'], 'Tsingtao\'nun düşmesiyle Almanya Uzak Doğu\'daki dayanağını yitirdi; Shandong\'daki Alman hakları sonradan Paris\'te Japonya\'ya bırakıldı.'),
  ('I. Dünya Savaşı\'nda Avustralya\'nın Alman Yeni Gine\'sini, Yeni Zelanda\'nın da Alman Samoa\'sını ele geçirmesi bu toprakların savaş sonrası statüsünü nasıl etkilemiştir?', 'Bu topraklar Milletler Cemiyeti mandası olarak işgalci devletlere bırakıldı', ['Bu topraklar Almanya\'ya geri verildi', 'Bu topraklar ABD\'ye satıldı', 'Bu topraklar savaşın hemen ardından halk oylamasıyla bağımsız devletler hâline geldi'], 'Paris\'te Alman sömürgeleri manda sistemine bağlandı; Pasifik adaları C tipi manda olarak onları işgal eden dominyonlara verildi.'),
  ('Ekim-Kasım 1918\'de Alman donanmasının son bir umutsuz deniz harekâtına çıkarılma emrine karşı denizcilerin ayaklandığı ve devrimin yayıldığı liman kenti hangisidir?', 'Kiel', ['Hamburg', 'Bremen', 'Danzig'], 'Kiel isyanı birkaç gün içinde işçi ve asker konseyleriyle Almanya\'nın büyük kentlerine yayıldı ve monarşinin sonunu getirdi.'),
  ('Tahttan çekildiği açıklanan Kayzer II. Wilhelm Kasım 1918\'de hangi ülkeye sığınmış ve ömrünün geri kalanını orada geçirmiştir?', 'Hollanda', ['İsviçre', 'İsveç', 'Danimarka'], 'Tarafsız Hollanda, İtilaf Devletleri\'nin yargılama amacıyla yaptığı iade taleplerini reddetti; Wilhelm 1941\'de Doorn\'da öldü.'),
  ('Savaştan sonra Almanya\'da yaygınlaşan \'sırttan bıçaklanma\' efsanesi neyi iddia ediyordu?', 'Ordunun cephede yenilmediği, iç cephedeki sosyalistler ve siviller tarafından ihanete uğradığı', ['Almanya\'nın savaşı İngiltere ile Rusya arasında yapılmış gizli bir antlaşma yüzünden kaybettiği', 'Kayzer\'in kendi generallerince öldürüldüğü', 'Avusturya\'nın Almanya\'ya bilerek ihanet ettiği'], 'Efsane, ateşkesi imzalayan sivil cumhuriyetçileri suçlayarak Weimar Cumhuriyeti\'ni baştan meşruiyet sorunuyla karşı karşıya bıraktı ve aşırı sağ tarafından istismar edildi.'),
  ('1848\'den beri tahtta olan ve Kasım 1916\'da ölen Avusturya-Macaristan imparatoru kimdir?', 'Franz Joseph', ['I. Karl', 'Franz Ferdinand', 'II. Joseph'], 'Franz Joseph\'in altmış sekiz yıllık saltanatı savaşın ortasında sona erdi; yerine yeğeninin oğlu I. Karl geçti.'),
  ('I. Karl\'ın Ekim 1918\'de imparatorluğu uluslardan oluşan bir federasyona dönüştürmeyi öneren bildirisi neden sonuç vermemiştir?', 'Çek, Güney Slav ve Polonyalı liderler artık tam bağımsızlık peşindeydi', ['Bildiri Almanya tarafından hemen reddedildi', 'Bildirinin Almanya tarafından hemen reddedilmesi ve Viyana\'nın Alman birliklerince işgal edilmesi', 'Bildiri yalnızca Macar topraklarını kapsıyordu'], 'Yenilgi kesinleşmişken yapılan reform önerisi geç kaldı; uluslar birkaç gün içinde kendi devletlerini ilan ettiler.'),
  ('28 Ekim 1918\'de Prag\'da bağımsızlığı ilan edilen devletin ilk cumhurbaşkanı kimdir?', 'Tomáš Masaryk', ['Edvard Beneš', 'Jan Masaryk', 'Milan Štefánik'], 'Masaryk, savaş boyunca yurt dışında Çekoslovak bağımsızlığı için çalıştı ve yeni devletin ilk cumhurbaşkanı oldu; 1935\'e kadar görevde kaldı.'),
  ('Polonya\'nın 11 Kasım 1918\'de bağımsızlığını kazanmasıyla devletin başına geçen ve ulusal kahraman sayılan lider kimdir?', 'Józef Piłsudski', ['Roman Dmowski', 'Ignacy Paderewski', 'Władysław Sikorski'], 'Piłsudski 11 Kasım 1918\'de Varşova\'da askerî yetkiyi devraldı ve kısa süre sonra devlet başkanı oldu.'),
  ('Polonya\'nın I. Dünya Savaşı sonunda yeniden bağımsız bir devlet olarak ortaya çıkabilmesini mümkün kılan durum nedir?', 'Toprağını paylaşan üç imparatorluğun da savaş sonunda çökmesi', ['Polonya\'nın savaş boyunca tarafsız kalması', 'Polonya\'nın savaş boyunca tarafsız kalıp iki taraftan da güvence alması', 'Polonya\'nın Fransa\'nın sömürgesi olması'], '18. yüzyıldan beri Polonya\'yı bölen Rusya, Almanya ve Avusturya-Macaristan\'ın aynı anda yıkılması bağımsızlık için eşsiz bir fırsat yarattı.'),
  ('12 Kasım 1918\'de Viyana\'da ilan edilen cumhuriyet, başlangıçta Almanya ile birleşme isteğini yansıtan hangi adı kullanmıştır?', 'Alman-Avusturya Cumhuriyeti', ['Tuna Cumhuriyeti', 'Büyük Avusturya ve Tuna Federasyonu', 'Habsburg Cumhuriyeti'], 'Yeni cumhuriyet Almanya ile birleşmeyi amaçlıyordu; Saint-Germain Antlaşması bu adı ve birleşmeyi yasakladı.'),
  ('Çariçe Aleksandra üzerindeki etkisiyle Rus monarşisinin itibarını zedeleyen ve Aralık 1916\'da bir grup aristokrat tarafından öldürülen Sibiryalı köylü kökenli \'kutsal adam\' kimdir?', 'Grigori Rasputin', ['Sergey Witte', 'Pyotr Stolıpin', 'Georgi Gapon'], 'Prens Yusupov ve arkadaşlarınca öldürülen Rasputin\'in saraydaki nüfuzu, çarlık rejiminin çürümüşlüğünün simgesi olarak görülüyordu.'),
  ('Rusya\'da Şubat 1917 Devrimi\'nin Petrograd\'da hangi olayla başladığı kabul edilir?', 'Dünya Kadınlar Günü\'nde ekmek kuyruklarındaki kadınların başlattığı gösterilerle', ['Çarın Duma\'yı topa tutmasıyla', 'Bolşeviklerin Kışlık Saray\'ı basmasıyla', 'Ordunun Galiçya\'da Almanlara toplu olarak teslim olduğunun başkentte resmen duyurulmasıyla'], 'Ekmek kıtlığına karşı kadın işçilerin gösterileri birkaç gün içinde genel greve dönüştü; askerlerin halka katılmasıyla çarlık yıkıldı.'),
  ('Şubat 1917\'den Ekim\'e kadar Rusya\'da yetkinin Geçici Hükümet ile Petrograd Sovyeti arasında bölünmesine ne ad verilir?', 'İkili iktidar', ['Anayasal monarşi', 'Proletarya diktatörlüğü', 'Kurucu iktidar'], 'Geçici Hükümet resmî yetkiyi elinde tutarken askerler ve işçiler üzerinde fiilî söz Petrograd Sovyeti\'ndeydi; bu durum hükümeti zayıflattı.'),
  ('Almanya\'nın 1917\'de sürgündeki Lenin\'in İsviçre\'den Rusya\'ya dönüşüne kendi toprakları üzerinden izin vermesinin amacı neydi?', 'Savaş karşıtı devrimcilerle Rusya\'yı içten çökertip savaştan çıkarmak', ['Lenin\'i yolda tutuklayıp yargılamak', 'Rusya\'yla gizli bir ittifak kurmak', 'Lenin\'in İsviçre\'de kalıp Almanya\'da güçlü bir sosyalist parti kurmasını engellemek'], 'Lenin\'in \'mühürlü vagonla\' dönüşü, Almanya\'nın doğu cephesini kapatma stratejisinin bir parçasıydı.'),
  ('Lenin\'in Nisan 1917\'de Rusya\'ya dönüşünün ardından açıkladığı ve \'Bütün iktidar sovyetlere\' çağrısını içeren programa ne ad verilir?', 'Nisan Tezleri', ['Komünist Manifesto', 'Ne Yapmalı?', 'Devlet ve Devrim'], 'Nisan Tezleri Geçici Hükümet\'e hiçbir destek verilmemesini, savaşın bitirilmesini ve toprağın köylüye dağıtılmasını öngörüyordu.'),
  ('Ekim 1917\'de Kışlık Saray\'a yapılan saldırının işareti olarak top atışı yaptığı kabul edilen kruvazör hangisidir?', 'Avrora', ['Potemkin', 'Varyag', 'Kniaz Suvorov'], 'Avrora kruvazörü bugün Sankt-Peterburg\'da müze gemisi olarak durmaktadır; 1905\'teki ünlü isyan ise Potemkin zırhlısında yaşanmıştı.'),
  ('Bolşeviklerin iktidarı aldıkları gün Sovyetler Kongresi\'nde kabul ettirdikleri Toprak Kararnamesi neyi öngörüyordu?', 'Büyük toprak sahiplerinin, kilisenin ve devletin topraklarının köylülere bırakılmasını', ['Bütün toprakların hemen devlet çiftliklerine dönüştürülmesini ve köylülerin ücretli işçi olmasını', 'Toprağın soylulara geri verilmesini', 'Köylülerin toprak vergisini ikiye katlamayı'], 'Kararname köylülerin fiilen el koyduğu toprakları meşrulaştırdı; kolektifleştirme ise ancak 1920\'lerin sonunda Stalin döneminde geldi.'),
  ('Aralık 1917\'de karşı devrimle mücadele amacıyla kurulan ve Feliks Dzerjinski\'nin yönettiği Sovyet gizli polis örgütü hangisidir?', 'Çeka', ['NKVD', 'KGB', 'Ohrana'], 'Çeka, iç savaş döneminde Kızıl Terör\'ün başlıca aracı oldu; daha sonra GPU, NKVD ve KGB gibi adlarla sürdü. Ohrana ise çarlık döneminin gizli polisidir.'),
  ('Rus Sosyal Demokrat İşçi Partisi\'nin 1903\'teki kongresinde ortaya çıkan bölünmede, Lenin\'in grubunun karşısında yer alan ılımlı kanada ne ad verilmiştir?', 'Menşevikler', ['Narodnikler', 'Kadetler', 'Esirler'], 'Bölünme parti üyeliğinin koşulları üzerine çıktı; Lenin\'in yanlıları oylamadaki üstünlükten dolayı \'çoğunluk\' anlamında Bolşevik adını aldı.'),
  ('Bolşevik hükümetinin Mart 1918\'de başkenti Petrograd\'dan Moskova\'ya taşımasının temel nedeni hangisidir?', 'Petrograd\'ın Alman ordusu ve sınır tehdidine fazla yakın olması', ['Moskova\'nın bir liman kenti olması', 'Petrograd\'ın tamamen yıkılmış ve yaşanmaz hâle gelmesi', 'Moskova\'nın işçi nüfusunun daha az olması'], 'Alman kuvvetlerinin Baltık\'taki ilerleyişi Petrograd\'ı savunmasız bıraktı; Moskova o tarihten beri başkenttir.'),
  ('Rus İç Savaşı\'nda Sibirya\'da kendini \'Yüce Hükümdar\' ilan eden ve 1920\'de kurşuna dizilen Beyaz Ordu lideri kimdir?', 'Amiral Aleksandr Kolçak', ['General Anton Denikin', 'General Pyotr Vrangel', 'General Nikolay Yudeniç'], 'Kolçak\'ın ordusu 1919\'da Volga\'ya kadar ilerledi ama geri püskürtüldü; Kolçak İrkutsk\'ta Bolşeviklere teslim edilip idam edildi.'),
  ('Beyaz Orduların Rus İç Savaşı\'nı kaybetmesinin nedenleri arasında aşağıdakilerden hangisi yer almaz?', 'Merkezî Rusya\'nın sanayi ve demiryolu kavşaklarını ellerinde tutmaları', ['Coğrafi olarak dağınık olup eş güdüm sağlayamamaları', 'Köylülere toprak konusunda güven verememeleri', 'Yabancı müdahaleyle anılmaları nedeniyle halkta milliyetçi bir tepki uyandırmaları'], 'Merkezî Rusya\'nın sanayi bölgeleri ve demiryolu ağı Kızılların elindeydi; bu, Bolşeviklere iç hatlardan savaşma üstünlüğü sağladı.'),
  ('İç savaş yıllarında Bolşeviklerin uyguladığı ve köylülerin tahıl fazlasına zorla el konulmasını içeren ekonomik politika hangi adla anılır?', 'Savaş Komünizmi', ['Yeni Ekonomik Politika', 'Beş Yıllık Plan', 'Kolektifleştirme'], 'Savaş Komünizmi sanayiyi millîleştirdi, özel ticareti yasakladı ve tahıla el koydu; sonuçta üretim çöktü ve köylü direnişi yaygınlaştı.'),
  ('Mart 1921\'de devrimin öncüsü sayılan Kronştad denizcilerinin Bolşeviklere karşı ayaklanması Lenin\'i hangi adımı atmaya yöneltmiştir?', 'Savaş Komünizmi\'ni bırakıp sınırlı piyasa serbestliği tanımaya', ['Bütün sovyetleri feshedip anayasal monarşiyi geri getirmeye ve Kurucu Meclis\'i toplamaya', 'Almanya\'ya savaş ilan etmeye', 'Parti içinde çok partili seçimlere izin vermeye'], 'Kronştad isyanı kanla bastırıldı; ancak aynı ay Lenin, köylüye vergi sonrası ürününü satma hakkı tanıyan ekonomik geri adımı açıkladı.'),
  ('Dünya devrimini yaymak amacıyla Mart 1919\'da Moskova\'da kurulan uluslararası komünist örgüt hangisidir?', 'Komintern', ['Birinci Enternasyonal', 'Kominform', 'Varşova Paktı'], 'Komintern, dünyadaki komünist partileri Moskova\'nın yönlendirmesine bağladı; 1943\'te dağıtıldı. Kominform ise 1947\'de kurulmuştur.'),
  ('Rus İç Savaşı sırasında İngiltere, Fransa, ABD ve Japonya\'nın Rusya\'nın kıyı bölgelerine asker çıkarmasının başlangıçtaki gerekçesi neydi?', 'Almanya\'ya karşı doğu cephesini yeniden açmak ve depolanmış savaş malzemesini korumak', ['Rusya\'yı aralarında sömürge olarak paylaşmak', 'Bolşevik hükümetini resmen tanıyıp desteklemek', 'Rus çarını yeniden tahta çıkarmak üzere doğrudan Moskova\'ya yürüyüp kenti ele geçirmek'], 'Müdahale 1918\'de Brest-Litovsk sonrası Alman tehdidine karşı başladı, ardından Beyazlara destek biçimine dönüştü; 1920 civarında büyük ölçüde sona erdi.'),
  ('Paris Barış Konferansı\'nın işleyişiyle ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Yenilen devletler görüşmelere katılamadı, koşullar onlara hazır biçimde sunuldu', ['Almanya görüşmelerde eşit oy hakkıyla temsil edildi', 'Konferansa Sovyet Rusya\'nın heyeti başkanlık etti', 'Kararlar, yenilenler de dâhil olmak üzere bütün katılımcı devletlerin oy birliğiyle alındı'], 'Kararları büyük ölçüde dört büyük devletin liderleri aldı; Almanya\'ya antlaşma metni yazılı görüşleri sınırlı ölçüde alınarak dayatıldığı için Almanlar ona \'Diktat\' dedi.'),
  ('Paris\'te Fiume (Rijeka) kentinin İtalya\'ya verilmesi isteği reddedilince konferansı bir süre protesto ederek terk eden İtalyan başbakanı kimdir?', 'Vittorio Emanuele Orlando', ['Giovanni Giolitti', 'Antonio Salandra', 'Francesco Nitti'], 'Orlando\'nun eli boş dönmesi İtalya\'da \'sakatlanmış zafer\' söylemini besledi ve milliyetçi tepkiyi güçlendirdi.'),
  ('İtalyan milliyetçilerinin barış antlaşmalarından sonra kullandığı \'sakatlanmış zafer\' ifadesi hangi duyguyu yansıtır?', 'Savaşa katılmanın karşılığında vaat edilen toprakların alınamamasından doğan hayal kırıklığını', ['İtalya\'nın savaşta yenilip toprak kaybetmesinin acısını', 'İtalya\'nın savaşta Avusturya\'ya yenilip kuzeydeki topraklarının büyük kısmını kaybetmesinin acısını', 'Avusturya\'yla kurulan yeni ittifakın getirdiği güveni'], 'Londra Antlaşması\'nın vaatleri, özellikle Dalmaçya, tam karşılanmadı; bu öfke faşist hareketin yükselişinde kullanıldı.'),
  ('Paris\'te Almanya\'nın Shandong\'daki haklarının Çin\'e değil Japonya\'ya verilmesi Çin\'de hangi gelişmeye yol açmıştır?', 'Öğrenci gösterileriyle başlayan 4 Mayıs Hareketi\'ne', ['Çin\'in Milletler Cemiyeti\'ne ilk kurucu üye olmasına', 'Çin\'de imparatorluğun yeniden kurulmasına', 'Çin\'in Japonya ile ittifak yapmasına'], '1919\'daki 4 Mayıs Hareketi Çin milliyetçiliğini ve modernleşme tartışmalarını canlandırdı; Çin heyeti Versay Antlaşması\'nı imzalamadı.'),
  ('Versay Antlaşması\'nın 28 Haziran 1919\'da imzalanması hangi olayın yıl dönümüne denk gelir?', 'Saraybosna suikastının', ['Kiel isyanının', 'Marne Muharebesi\'nin', 'ABD\'nin savaşa girişinin'], 'Antlaşma, savaşın kıvılcımı olan Franz Ferdinand suikastından tam beş yıl sonra Aynalı Salon\'da imzalandı.'),
  ('Versay Antlaşması\'nın Almanya ve müttefiklerini savaşın çıkmasından sorumlu tutan ve tazminat istemlerine hukuki dayanak oluşturan maddesi hangi adla anılır?', 'Savaş suçluluğu maddesi (231. madde)', ['Kollektif güvenlik maddesi (10. madde)', 'Manda maddesi (22. madde)', 'Ren maddesi (42. madde)'], '231. madde Almanya\'da derin bir aşağılanma duygusu yarattı ve antlaşmanın revizyonu talebinin merkezine yerleşti.'),
  ('Versay Antlaşması Alman kara ordusunun mevcudunu en çok kaç kişiyle sınırlamıştır?', '100.000', ['50.000', '250.000', '500.000'], 'Ordu 100.000 kişiyle sınırlandı, zorunlu askerlik yasaklandı; ayrıca tank, askerî uçak ve denizaltı bulundurması da yasaklandı.'),
  ('Versay Antlaşması\'nın Alman silahlı kuvvetlerine getirdiği yasaklar arasında aşağıdakilerden hangisi yoktur?', 'Polis teşkilatı kurulması', ['Askerî hava kuvveti bulundurulması', 'Denizaltı bulundurulması', 'Zorunlu askerlik uygulanması'], 'Antlaşma hava kuvvetini, denizaltıları, tankları ve zorunlu askerliği yasakladı; iç düzen için polis teşkilatı ise yasak kapsamında değildi.'),
  ('Versay Antlaşması\'yla Polonya\'ya denize çıkış sağlamak için verilen topraklar Doğu Prusya\'yı Almanya\'nın geri kalanından ayırmıştır. Bu toprak şeridine ne ad verilir?', 'Polonya Koridoru', ['Baltık Kapısı', 'Vistül Köprüsü', 'Prusya Şeridi'], 'Koridor ve onun ucundaki Danzig, savaşlar arası dönemde Almanya-Polonya ilişkilerinin en hassas konusu oldu ve 1939 bunalımının merkezine yerleşti.'),
  ('Nüfusunun büyük çoğunluğu Alman olduğu hâlde Versay Antlaşması\'yla Milletler Cemiyeti koruması altında \'serbest şehir\' yapılan Baltık limanı hangisidir?', 'Danzig', ['Königsberg', 'Stettin', 'Riga'], 'Danzig Polonya\'nın gümrük alanına bağlandı; kentin statüsü 1939\'da Hitler\'in Polonya\'dan taleplerinin başında geldi.'),
  ('1921\'de Tazminat Komisyonu Almanya\'nın ödeyeceği toplam tutarı 132 milyar altın mark olarak belirlemiştir. Bu tutarın 1923\'te tümüyle durdurulan ödemelerle bağlantılı olarak yol açtığı doğrudan gelişme hangisidir?', 'Fransa ile Belçika\'nın Ruhr bölgesini işgal etmesi', ['Almanya\'nın Milletler Cemiyeti\'ne kabul edilmesi', 'Almanya\'nın Polonya\'yı işgal etmesi', 'Almanya\'nın Avusturya\'yı ilhak etmesi'], 'Almanya\'nın ödemeleri aksatması üzerine Fransız ve Belçika birlikleri Ocak 1923\'te sanayi bölgesi Ruhr\'a girdi; bu, Alman hiperenflasyonunu da derinleştirdi.'),
  ('Versay Antlaşması\'nı \'Kartaca barışı\' diye eleştiren ve tazminatların Avrupa ekonomisini yıkacağını savunan 1919 tarihli kitabın yazarı İngiliz iktisatçı kimdir?', 'John Maynard Keynes', ['Adam Smith', 'Friedrich Hayek', 'David Ricardo'], 'Keynes\'in \'Barışın Ekonomik Sonuçları\' adlı kitabı antlaşmaya karşı İngiliz ve Amerikan kamuoyunda etkili oldu.'),
  ('ABD Senatosu\'nun Versay Antlaşması\'nı onaylamamasının Milletler Cemiyeti üzerindeki en önemli sonucu hangisidir?', 'Örgütün en güçlü ekonomiye sahip devletten yoksun kalarak etkinliğini yitirmesi', ['Örgütün merkezinin New York\'a taşınması', 'Örgütün Amerikan ordusunun denetimine girmesi', 'Örgütün resmen kurulmadan dağılması'], 'Kuruluşunu Wilson\'ın önerdiği örgüte ABD katılmadı; bu durum yaptırımların uygulanmasını ve örgütün caydırıcılığını zayıflattı.'),
  ('Bulgaristan ile imzalanan 1919 Neuilly Antlaşması\'yla Bulgaristan\'ın en ağır kaybı aşağıdakilerden hangisi olmuştur?', 'Batı Trakya\'yı yitirerek Ege Denizi\'ne çıkışını kaybetmesi', ['Sofya\'nın Romanya\'ya bırakılması', 'Karadeniz kıyılarının tümünü kaybetmesi', 'Tuna Nehri üzerindeki bütün limanlarını Sırbistan\'a bırakması'], 'Batı Trakya önce İtilaf denetimine, ardından Yunanistan\'a verildi; Bulgaristan ayrıca bazı sınır bölgelerini Sırp-Hırvat-Sloven Krallığı\'na bıraktı.'),
  ('Macaristan ile İtilaf Devletleri arasında 4 Haziran 1920\'de imzalanan antlaşma hangisidir?', 'Trianon Antlaşması', ['Neuilly Antlaşması', 'Sevr Antlaşması', 'Saint-Germain Antlaşması'], 'Trianon, Versay sarayı bahçesindeki Büyük Trianon Sarayı\'nda imzalandı; Macaristan\'da hâlâ ulusal yas günü olarak anılır.'),
  ('Trianon Antlaşması\'nın Macaristan açısından sonuçları değerlendirildiğinde savaşlar arası dönemde Macar dış politikasının temel hedefi hangisi olmuştur?', 'Kaybedilen toprakları geri almak amacıyla antlaşmanın revizyonu', ['Romanya ile birleşerek ortak bir krallık kurmak', 'Sovyetler Birliği ile askerî ittifak kurarak batıya karşı denge sağlamak', 'Kalıcı tarafsızlık ilan ederek ittifaklardan uzak durmak'], 'Macaristan topraklarının yaklaşık üçte ikisini ve milyonlarca Macarı komşu ülkelerde bıraktı; bu revizyonizm onu 1930\'larda Almanya ve İtalya\'ya yaklaştırdı.'),
  ('Milletler Cemiyeti\'nin Konsey ve Genel Kurul kararlarında çoğunlukla oy birliği aranması örgütün işleyişini nasıl etkilemiştir?', 'Tek bir üyenin itirazı kararları engelleyebildiği için hızlı ve etkili eylem zorlaştı', ['Büyük devletlere küçükler üzerinde veto hakkı tanıyarak örgütü güçlendirdi', 'Kararların yalnız ABD\'nin onayıyla alınmasını sağladı', 'Kararların yalnız ABD ile İngiltere\'nin ortak onayıyla alınmasını sağlayarak süreci büyük ölçüde hızlandırdı'], 'Oy birliği kuralı egemenlik kaygılarını yatıştırıyordu ama bunalım anlarında kararların gecikmesine ve sulandırılmasına yol açtı.'),
  ('Milletler Cemiyeti Paktı\'nın 16. maddesi saldırgan bir devlete karşı öncelikle hangi tür yaptırımı öngörüyordu?', 'Ekonomik ve mali yaptırımlar', ['Otomatik askerî müdahale', 'Saldırganın üyelikten ömür boyu atılması', 'Saldırgan devletin topraklarının paylaşılması'], 'Pakt öncelikle ticari ve mali ilişkilerin kesilmesini öngördü; askerî önlem için ise Konsey yalnızca tavsiyede bulunabiliyordu.'),
  ('Milletler Cemiyeti\'nin mülteci yüksek komiseri olarak vatansız kalan mültecilere kimlik belgesi verilmesini sağlayan ve 1922\'de Nobel Barış Ödülü alan Norveçli kâşif kimdir?', 'Fridtjof Nansen', ['Roald Amundsen', 'Henrik Ibsen', 'Christian Lange'], 'Nansen pasaportu, özellikle Rus devriminden kaçan ve vatandaşlıktan çıkarılanların seyahat ve iş bulmasını kolaylaştırdı.'),
  ('Versay Antlaşması\'yla 1919\'da kurulan ve çalışma koşullarını iyileştirmeye yönelik uluslararası standartlar geliştiren örgüt hangisidir?', 'Uluslararası Çalışma Örgütü', ['Dünya Sağlık Örgütü', 'Uluslararası Para Fonu', 'Dünya Ticaret Örgütü'], 'ILO, Milletler Cemiyeti\'nden sonra da varlığını sürdürdü ve bugün Birleşmiş Milletler\'e bağlı bir uzmanlık kuruluşudur.'),
  ('Sovyetler Birliği\'nin Milletler Cemiyeti\'nden 1939 sonunda ihraç edilmesinin nedeni nedir?', 'Finlandiya\'ya saldırması', ['Polonya ile antlaşma yapması', 'Japonya\'ya savaş ilan etmesi', 'Komintern\'i kurması'], '1934\'te üye olan SSCB, Kasım 1939\'da Finlandiya\'ya saldırınca Aralık 1939\'da örgütten çıkarıldı; bu, Cemiyet\'in son önemli kararlarından biriydi.'),
  ('Polonyalı general Żeligowski\'nin 1920\'de Litvanya\'nın talep ettiği Vilnius\'u ele geçirmesine Milletler Cemiyeti\'nin etkili bir karşılık verememesi neyi göstermiştir?', 'Örgütün oldubittiler karşısında kararını uygulatacak gücü olmadığını', ['Örgütün Polonya\'yı hemen üyelikten çıkardığını', 'Litvanya\'nın kenti kendiliğinden bıraktığını', 'Kentin Milletler Cemiyeti\'nin doğrudan yönetimine verilip iki ülke arasında tampon bölge yapıldığını'], 'Polonya Vilnius\'u elinde tuttu ve 1923\'te Büyükelçiler Konferansı bu durumu tanıdı; Litvanya ile Polonya arasındaki ilişkiler uzun süre gergin kaldı.'),
  ('1922 Washington Deniz Antlaşması\'nda ABD, İngiltere ve Japonya\'nın büyük savaş gemisi tonajları 5:5:3 oranına bağlanmıştır. ABD\'nin hakkı 525.000 ton olarak belirlendiğinde Japonya\'nın hakkı yaklaşık ne olur?', '315.000 ton', ['175.000 ton', '262.500 ton', '420.000 ton'], 'Oran 5\'e 3 olduğuna göre Japonya\'nın hakkı 525.000 × 3/5 = 315.000 tondur.'),
  ('1921-1922 Washington Konferansı\'nda imzalanan Dörtlü Pasifik Antlaşması\'nın İngiltere açısından önemli sonucu nedir?', 'Japonya ile 1902\'den beri süren ittifakın sona erdirilmesi', ['İngiltere\'nin Hong Kong\'u Çin\'e iade etmesi', 'İngiltere\'nin Hong Kong\'u ve Kowloon\'u Çin\'e iade etmeyi kabul etmesi', 'İngiltere\'nin Japonya\'ya Singapur\'u devretmesi'], 'ABD\'nin kaygıları üzerine İngiliz-Japon ittifakı, Pasifik\'teki statükoya saygı taahhüdü içeren dörtlü bir antlaşmayla yer değiştirdi.'),
  ('Almanya ile Sovyet Rusya\'nın birbirlerinden savaş tazminatı istemekten vazgeçip diplomatik ilişki kurduğu 1922 tarihli antlaşma hangisidir?', 'Rapallo Antlaşması', ['Locarno Antlaşması', 'Riga Antlaşması', 'Brest-Litovsk Antlaşması'], 'Rapallo, Versay düzeninin dışladığı iki devletin yakınlaşmasıydı; ardından gizli askerî iş birliği de gelişti.'),
  ('Alman hükümetinin 1923\'te Ruhr işgaline karşı işçi ve memurlara çağrısı nasıl bir direniş biçimiydi?', 'Pasif direniş, yani işgalciler için çalışmayı reddetme', ['Silahlı gerilla savaşı', 'Fransa\'ya karşı resmî savaş ilanı', 'Ruhr\'un bağımsızlığının ilanı'], 'Hükümet greve çıkan işçilerin ücretlerini para basarak ödedi; bu da zaten yükselen enflasyonu hiperenflasyona dönüştürdü.'),
  ('1924 Dawes Planı\'nın Alman ekonomisi üzerindeki etkisi hangi düzenlemeye dayanıyordu?', 'Tazminat taksitlerinin yeniden düzenlenmesi ve ABD\'den kredi akışının sağlanması', ['Tazminatların tümüyle ve kalıcı olarak silinmesi, savaş borçlarının da karşılıklı affedilmesi', 'Almanya\'nın bütün sanayisinin Fransa\'ya devredilmesi', 'Almanya\'nın altın standardından çıkarılması'], 'Plan yıllık ödemeleri Almanya\'nın gücüne göre ayarladı ve Amerikan kredileriyle ekonomiyi canlandırdı; ancak Almanya\'yı ABD sermayesine bağımlı hâle getirdi.'),
  ('1929\'da tazminat toplamını düşüren ve ödemeleri 1988\'e kadar uzanan taksitlere bağlayan plan hangisidir?', 'Young Planı', ['Dawes Planı', 'Marshall Planı', 'Hoover Moratoryumu'], 'Owen Young\'ın başkanlığındaki komitenin hazırladığı plan, Almanya\'da milliyetçiler tarafından halkoylamasına götürülerek protesto edildi; Hitler bu kampanyayla ulusal ölçekte tanındı.'),
  ('1925 Locarno antlaşmalarında Almanya\'nın sınırlarıyla ilgili tutumu en iyi nasıl özetlenir?', 'Batı sınırlarını gönüllü olarak tanıdı, doğu sınırları için yalnız hakem antlaşmalarını kabul etti', ['Bütün sınırlarını kesin olarak tanıyıp doğuda ve batıda revizyon isteminden tümüyle vazgeçti', 'Batı sınırını reddedip doğu sınırlarını kabul etti', 'Hiçbir sınırını tanımadı, yalnızca silahsızlanmayı kabul etti'], 'Locarno\'da Fransa, Belçika ve Almanya sınırları İngiltere ve İtalya güvencesine bağlandı; Polonya ve Çekoslovakya ile sınırlar ise açık bırakıldı.'),
  ('1928 Kellogg-Briand Paktı\'nın temel zayıflığı aşağıdakilerden hangisidir?', 'Savaşı ulusal politika aracı olarak reddetse de ihlale karşı hiçbir yaptırım içermemesi', ['Yalnızca iki devlet arasında imzalanmış olması', 'Sovyetler Birliği\'nin imzalamasını yasaklaması', 'Milletler Cemiyeti\'ni resmen feshederek onun yerine yeni bir güvenlik örgütü kurmaması'], 'Paktı onlarca devlet imzaladı; ancak uygulama mekanizması olmadığından 1930\'lardaki saldırıları önleyemedi.'),
  ('1919\'da Alman Ulusal Meclisi\'nin Berlin yerine Weimar kentinde toplanmasının temel nedeni nedir?', 'Berlin\'deki devrimci kargaşa ve sokak çatışmaları', ['Weimar\'ın Almanya\'nın en büyük sanayi kenti olması', 'İtilaf Devletleri\'nin Berlin\'i işgal etmiş olması', 'Kayzer\'in Berlin\'de hâlâ hüküm sürmesi'], 'Spartakist ayaklanmasının yaşandığı başkent güvensiz görülünce meclis sakin bir taşra kenti olan Weimar\'da toplandı; cumhuriyet de adını buradan aldı.'),
  ('Weimar Anayasası\'nın 48. maddesi cumhuriyetin çöküşünde neden kritik rol oynamıştır?', 'Cumhurbaşkanına olağanüstü durumlarda meclissiz kararnameyle yönetme yetkisi vermesi', ['Siyasi partilerin kurulmasını tümüyle yasaklaması', 'Ordunun başına seçilmiş bir sivil yerine kayzeri getirmesi', 'Kadınların oy hakkını kaldırarak seçmen tabanını daraltması ve seçimleri dolaylı hâle getirmesi'], '1930\'dan itibaren hükümetler meclis çoğunluğuna değil cumhurbaşkanlığı kararnamelerine dayandı; bu uygulama parlamenter düzeni içten aşındırdı.'),
  ('Weimar Cumhuriyeti\'nde katıksız nispi temsil sisteminin uygulanmasının siyasi sonucu aşağıdakilerden hangisidir?', 'Mecliste çok sayıda partinin bulunması ve istikrarsız koalisyon hükümetleri', ['Tek partili bir yönetimin hemen kurulması', 'Yalnızca iki büyük partinin meclise girebilmesi ve küçük partilerin tümüyle dışarıda kalması', 'Seçimlerin hiç yapılmaması'], 'Küçük partiler de kolayca meclise girebildiği için hükümet kurmak zorlaştı; Weimar döneminde hükümetler sık sık değişti.'),
  ('Ocak 1919\'da Berlin\'de çıkan komünist Spartakist ayaklanmasının bastırılması sırasında öldürülen iki önder hangileridir?', 'Rosa Luxemburg ve Karl Liebknecht', ['Kurt Eisner ve Ernst Toller', 'Ernst Thälmann ve Walter Ulbricht', 'Clara Zetkin ve August Bebel'], 'Ayaklanmayı hükümet adına bastıran gönüllü Freikorps birlikleri iki önderi gözaltında öldürdü; bu olay solun bölünmesini derinleştirdi.'),
  ('Savaştan dönen eski askerlerden oluşan ve Weimar\'ın ilk yıllarında hükümetçe sol ayaklanmaları bastırmak için kullanılan gönüllü sağcı birliklere ne ad verilir?', 'Freikorps', ['Stahlhelm', 'Reichswehr', 'Volkssturm'], 'Freikorps birlikleri cumhuriyete de düşmandı; birçok üyesi daha sonra Nazi hareketine katıldı.'),
  ('Hitler\'in Kasım 1923\'te Ludendorff ile birlikte Münih\'te Bavyera hükümetini devirmeye çalıştığı başarısız girişim hangi adla anılır?', 'Birahane Darbesi', ['Kapp Darbesi', 'Roma Yürüyüşü', 'Uzun Bıçaklar Gecesi'], 'Darbe polis ateşiyle dağıtıldı; Hitler yargılanıp hapse mahkûm edildi ve duruşmayı propaganda kürsüsüne çevirdi.'),
  ('Hitler\'in Birahane Darbesi\'nden sonra Landsberg Hapishanesi\'nde kaldığı dönemde kaleme aldığı kitap hangisidir?', 'Kavgam', ['Yirminci Yüzyılın Efsanesi', 'Batının Çöküşü', 'Üçüncü Reich'], 'Kitap Hitler\'in ırkçı dünya görüşünü, Yahudi düşmanlığını ve doğuda \'yaşam alanı\' hedefini ortaya koyuyordu.'),
  ('1923 hiperenflasyonundan en çok zarar gören toplumsal kesim aşağıdakilerden hangisidir?', 'Birikimlerini bankada tutan ve sabit gelirle yaşayan orta sınıf', ['Borçlarını değersiz parayla kapatabilen borçlular', 'Fabrika, arazi ve konut gibi taşınmaz varlıklara sahip olan büyük sanayiciler ile toprak sahipleri', 'Döviz kazancı olan ihracatçılar'], 'Tasarrufların ve emekli maaşlarının silinmesi orta sınıfın cumhuriyete güvenini sarstı; borçlular ve reel varlık sahipleri ise kazançlı çıktı.'),
  ('1923\'te kısa bir süre şansölyelik yapıp Rentenmark\'ı başlatan, ardından 1929\'daki ölümüne kadar dışişleri bakanı olarak Almanya\'yı uluslararası topluma yeniden kazandıran siyasetçi kimdir?', 'Gustav Stresemann', ['Heinrich Brüning', 'Franz von Papen', 'Hermann Müller'], 'Stresemann, Dawes Planı, Locarno ve Milletler Cemiyeti üyeliğiyle Weimar\'ın \'altın yıllarının\' mimarı sayılır.'),
  ('Nazi Partisi 1928 seçimlerinde 12, Eylül 1930\'da 107, Temmuz 1932\'de 230 sandalye kazanmıştır. Bu verilere göre aşağıdaki yorumlardan hangisi doğrudur?', 'Partinin asıl sıçraması Büyük Buhran\'ın başlamasından sonra gerçekleşti', ['Parti en yüksek seçmen desteğine Birahane Darbesi\'nin hemen ardından yapılan seçimde ulaştı', 'Partinin oyları 1928\'den 1932\'ye sürekli azaldı', 'Parti 1928\'de mecliste en büyük partiydi'], '1929 sonrasında işsizliğin artmasıyla Nazilerin sandalye sayısı kısa sürede on kat büyüdü; 1932 yazında en büyük parti oldular.'),
  ('Hitler\'in Ocak 1933\'te şansölyeliğe getirilmesinde Franz von Papen ve çevresindeki muhafazakârların temel hesabı neydi?', 'Hitler\'i az sayıda Nazi bakanla kuşatarak denetim altında tutabilecekleri', ['Hitler\'in birkaç hafta içinde kendiliğinden istifa edeceği', 'Nazilerin seçimlerde tamamen silineceği', 'Ordunun Hitler\'i birkaç ay içinde devirip Hohenzollern monarşisini geri getireceği'], 'İlk kabinede yalnızca üç Nazi vardı; Papen, Hitler\'i \'işe aldıklarını\' düşünüyordu. Bu hesap birkaç ay içinde çöktü.'),
  ('Şubat 1933\'teki Reichstag yangınının ardından çıkarılan kararnamenin en önemli sonucu hangisidir?', 'Temel hak ve özgürlüklerin askıya alınıp komünistlerin toplu tutuklanması', ['Nazi Partisi\'nin yangından sorumlu tutularak geçici olarak yasaklanması ve kapatılması', 'Hitler\'in şansölyelikten çekilmesi', 'Reichstag\'ın Münih\'e taşınması'], 'Reichstag Yangını Kararnamesi kişi özgürlüğünü, basın ve toplanma hakkını askıya aldı; Naziler muhaliflerini yasal kılıf altında bastırdı.'),
  ('Mart 1933\'te kabul edilen Yetki Yasası, Alman hükümetine hangi yetkiyi vermiştir?', 'Reichstag\'ın onayı olmadan, anayasaya aykırı olsa bile yasa çıkarma', ['Yalnızca dış politikada meclise danışmadan uluslararası antlaşma imzalayabilme', 'Cumhurbaşkanını seçimle görevden alma', 'Eyalet meclislerini yeniden seçme'], 'Yetki Yasası Weimar anayasasını fiilen işlevsiz bıraktı ve Hitler\'e yasal diktatörlük olanağı sağladı.'),
  ('Nazilerin 1933-1934 yıllarında devlet kurumlarını, eyaletleri, sendikaları ve dernekleri parti çizgisine bağlama sürecine ne ad verilir?', 'Gleichschaltung', ['Lebensraum', 'Anschluss', 'Blitzkrieg'], 'Bu süreçte sendikalar kapatıldı, partiler yasaklandı ve Temmuz 1933\'te Nazi Partisi tek yasal parti ilan edildi.'),
  ('Haziran 1934\'te Hitler\'in kendi SA önderlerini öldürttüğü \'Uzun Bıçaklar Gecesi\'nin temel amacı neydi?', 'Orduyla uzlaşmak için SA\'nın gücünü kırmak ve iç rakipleri tasfiye etmek', ['Komünist Parti\'nin yer altına çekilmiş örgütünü ve silahlı birliklerini tamamen dağıtmak', 'Kilise önderlerini susturmak', 'Avusturya\'yı ilhak etmeye hazırlanmak'], 'Ernst Röhm\'ün SA\'yı orduyla birleştirme isteği generalleri tedirgin ediyordu; tasfiyeyle Hitler ordunun desteğini sağladı ve muhafazakâr muhalifleri de yok etti.'),
  ('Ağustos 1934\'te Hindenburg\'un ölümünden sonra Hitler\'in aldığı unvan ve ordunun ona yönelik tutumu hangisinde doğru verilmiştir?', 'Cumhurbaşkanlığı ile şansölyeliği birleştirip Führer oldu; ordu doğrudan ona sadakat yemini etti', ['Halkoyuyla cumhurbaşkanı seçildi; ordu da anayasaya ve meclise bağlılık yemini etti', 'Kral ilan edildi; ordu kayzere bağlı kaldı', 'Başbakan oldu; ordu tarafsızlık ilan etti'], 'Askerlerin anayasaya değil Hitler\'in şahsına yemin etmesi, sonraki yıllarda orduda direnişi ahlaken de zorlaştırdı.'),
  ('Naziler iktidara geldikten birkaç hafta sonra, Mart 1933\'te Münih yakınlarında açılan ilk büyük toplama kampı hangisidir?', 'Dachau', ['Auschwitz', 'Treblinka', 'Bergen-Belsen'], 'Dachau başlangıçta siyasi muhalifler için kuruldu ve sonraki kampların örgütlenmesine model oldu.'),
  ('Eylül 1935\'te kabul edilen Nürnberg Yasaları\'nın temel içeriği nedir?', 'Yahudileri vatandaşlıktan çıkarıp Yahudilerle Almanlar arasındaki evliliği yasaklaması', ['Almanya\'da zorunlu askerliği yeniden getirip orduyu genişletmesi', 'Bütün siyasi partileri kapatıp Nazi Partisi\'ni tek yasal parti ilan ederek meclisi feshetmesi', 'Yahudi işletmelerine yönelik bir günlük boykot ilan etmesi'], 'Yasalar ırkçı ideolojiyi hukuk düzenine yerleştirdi; Yahudiler \'Reich vatandaşı\' olmaktan çıkarılıp ikinci sınıf uyruklara dönüştürüldü.'),
  ('Nazi Almanyası\'nda radyo, basın, sinema ve sanatı denetleyen Halkı Aydınlatma ve Propaganda Bakanlığı\'nın başındaki isim kimdir?', 'Joseph Goebbels', ['Hermann Göring', 'Heinrich Himmler', 'Alfred Rosenberg'], 'Goebbels ucuz \'halk radyosu\' üretimini destekleyerek propagandanın her eve ulaşmasını sağladı.'),
  ('Mayıs 1933\'te Berlin\'de ve birçok üniversite kentinde \'Alman ruhuna aykırı\' sayılan eserlerin öğrenciler tarafından toplu olarak ateşe verildiği olay hangi adla anılır?', 'Kitap yakma eylemleri', ['Kristal Gece', 'Uzun Bıçaklar Gecesi', 'Yozlaşmış Sanat Sergisi'], 'Heinrich Heine, Thomas Mann ve Freud gibi yazarların kitapları yakıldı; olay düşünce özgürlüğünün bastırılmasının simgesi oldu.'),
  ('Nazi rejiminin işçilere ucuz tatil, gezi ve eğlence olanakları sunan \'Neşe Yoluyla Güç\' (KdF) programının siyasi amacı nedir?', 'İşçilerin bağımsız sendikaların yokluğunda rejime bağlanmasını sağlamak', ['İşçilere grev hakkı tanıyıp ücretleri işverenlerle serbest toplu pazarlığa bırakmak', 'Kadınların fabrikalarda çalışmasını zorunlu kılmak', 'Turizm gelirleriyle savaş tazminatı ödemek'], 'Sendikalar kapatılıp yerine Alman Çalışma Cephesi kurulduktan sonra KdF, boş zamanı denetleyerek işçilerin rejime bağlılığını artırmayı amaçladı.'),
  ('Nazi rejiminin 1936\'da Göring yönetiminde başlattığı ve ekonomiyi dört yıl içinde savaşa hazır, kendi kendine yeterli hâle getirmeyi hedefleyen program hangisidir?', 'Dört Yıllık Plan', ['Beş Yıllık Plan', 'Dawes Planı', 'Schlieffen Planı'], 'Plan sentetik yakıt ve kauçuk üretimi gibi otarşi hedefleri içeriyordu; ekonominin silahlanmaya yönelmesini hızlandırdı.'),
  ('Nazi ideolojisinde kadının rolünü özetleyen \'Kinder, Küche, Kirche\' (çocuklar, mutfak, kilise) sloganı hangi politikayla uyumludur?', 'Kadınları anneliğe ve eve yönlendirip doğum oranını artırmaya çalışmak', ['Kadınların askerlikte ve cephede erkeklerle eşit görev almasını yasal güvenceye bağlamak', 'Kadınların siyasi partilerde yönetici olmasını teşvik etmek', 'Kadınların üniversiteye girişini zorunlu kılmak'], 'Rejim evlilik kredileri ve çok çocuklu annelere madalya gibi teşviklerle kadınları aileye yönlendirdi.'),
  ('Nazi Almanyası\'nda gençleri ideolojik olarak eğitmek amacıyla kurulan ve 1936\'dan sonra fiilen zorunlu hâle gelen erkek gençlik örgütü hangisidir?', 'Hitler Gençliği', ['Alman Kızlar Birliği', 'SA Gençlik Kolu', 'Wandervogel'], 'Hitler Gençliği spor, kamp ve askerî eğitimle gençleri rejime bağladı; kızlar için ayrı olarak Alman Kızlar Birliği vardı.'),
  ('Almanya\'nın Mart 1935\'te Versay Antlaşması\'nı açıkça çiğneyerek ilan ettiği karar hangisidir?', 'Zorunlu askerliğin yeniden getirilmesi', ['Ren bölgesine asker sokulması', 'Avusturya\'nın ilhakı', 'Milletler Cemiyeti\'nden çekilme'], 'Hitler aynı dönemde Luftwaffe\'nin varlığını da açıkladı; İngiltere, Fransa ve İtalya buna Stresa\'da ortak bir tepkiyle karşılık vermeye çalıştı.'),
  ('İtalya, İngiltere ve Fransa\'nın Nisan 1935\'te Stresa\'da bir araya gelmesinin amacı neydi?', 'Almanya\'nın Versay\'ı ihlal eden silahlanmasına karşı ortak tutum almak', ['Habeşistan\'ın paylaşımını kararlaştırmak', 'Sovyetler Birliği\'ne karşı ortak bir askerî ittifak kurmak ve Komintern\'i yasaklamak', 'İspanya İç Savaşı\'na ortak müdahale planlamak'], 'Stresa Cephesi kısa ömürlü oldu: İngiliz-Alman Deniz Antlaşması ve İtalya\'nın Habeşistan\'a saldırısı birliği birkaç ay içinde dağıttı.'),
  ('Nazilerin 1937\'de Münih\'te modern sanat eserlerini alay konusu yapmak için açtığı sergi hangi adla anılır?', 'Yozlaşmış Sanat Sergisi', ['Büyük Alman Sanatı Sergisi', 'Bauhaus Sergisi', 'Halkın Sanatı Fuarı'], 'Ekspresyonist ve soyut eserler \'yozlaşmış\' diye damgalandı; aynı yıllarda rejim onayladığı sanatı ayrı bir sergide sergiledi.'),
  ('Mussolini\'nin 1919\'da Milano\'da kurduğu ve faşist hareketin başlangıcı sayılan örgüt hangisidir?', 'Fasci di Combattimento', ['Ulusal Faşist Parti', 'Kara Gömlekliler Milisi', 'Fiume Lejyonu'], 'Hareket 1921\'de Ulusal Faşist Parti\'ye dönüştü; \'fascio\' kelimesi demet ve birlik anlamını taşır.'),
  ('İtalya\'da faşist milislerin 1920-1922 arasında sosyalist belediyelere, sendikalara ve gazetelere saldırması büyük toprak sahipleri ve sanayicilerin hangi kaygısından destek görmüştür?', 'Grev dalgası ve fabrika işgalleri karşısında devrim korkusu', ['Monarşinin kaldırılacağı korkusu', 'İtalya\'nın kuzey sınırının Fransa ve Yugoslavya tarafından işgal edileceği korkusu', 'Kilisenin topraklarına el konulacağı beklentisi'], '1919-1920 \'Kızıl İki Yıl\' döneminde artan grev ve işgaller mülk sahiplerini faşist şiddete göz yummaya ve onu finanse etmeye yöneltti.'),
  ('1924\'te faşistlerin seçim usulsüzlüklerini mecliste açıkça eleştirdikten kısa süre sonra kaçırılıp öldürülen sosyalist milletvekili kimdir?', 'Giacomo Matteotti', ['Antonio Gramsci', 'Filippo Turati', 'Carlo Rosselli'], 'Matteotti cinayeti Mussolini\'yi bunalıma soktu; muhalefetin meclisi boykot etmesi etkisiz kalınca Mussolini 1925 başında açık diktatörlüğe geçti.'),
  ('Mussolini\'nin 1929\'da Papalıkla imzaladığı ve Vatikan\'ı bağımsız bir devlet olarak tanıyan antlaşmalar hangi adla bilinir?', 'Lateran Antlaşmaları', ['Reichskonkordat', 'Roma Protokolleri', 'Milano Fermanı'], 'Antlaşmalar 1870\'ten beri süren \'Roma sorunu\'nu çözdü; Katoliklik devlet dini kabul edildi ve rejim Kilise\'nin desteğini kazandı.'),
  ('Mussolini\'nin İtalya\'nın buğday üretimini artırıp ithalata bağımlılığı azaltmak için başlattığı kampanya hangi adla anılır?', 'Tahıl Savaşı', ['Toprak Reformu', 'Ekmek Planı', 'Altın Hasat Seferi'], 'Tahıl Savaşı buğday üretimini artırdı ama verimli toprakların meyve ve zeytin gibi daha kârlı ürünlerden buğdaya kaydırılması ekonomik maliyet yarattı.'),
  ('İtalya\'nın Nisan 1939\'da işgal edip krallığını İtalyan tacına bağladığı Balkan ülkesi hangisidir?', 'Arnavutluk', ['Yunanistan', 'Yugoslavya', 'Bulgaristan'], 'Arnavutluk zaten büyük ölçüde İtalyan nüfuzu altındaydı; Kral Zogu ülkeden kaçtı ve taç III. Vittorio Emanuele\'ye geçti.'),
  ('Milletler Cemiyeti\'nin İtalya\'ya karşı 1935\'te aldığı ekonomik yaptırımların etkisiz kalmasının temel nedeni nedir?', 'Petrolün yaptırım dışında bırakılması ve Süveyş Kanalı\'nın İtalyan gemilerine açık tutulması', ['Yaptırımlara bütün üyelerin eksiksiz katılmasına rağmen İtalya\'nın kendi kaynaklarıyla tümüyle kendine yetmesi', 'Habeşistan\'ın yaptırımları reddetmesi', 'İtalya\'nın yaptırım kararından önce Cemiyet\'ten ayrılmış olması'], 'İngiltere ve Fransa, Mussolini\'yi Hitler\'e itmekten çekindikleri için en etkili araçları kullanmadı; savaş makinesi petrolle çalışmayı sürdürdü.'),
  ('Haziran 1936\'da Cenevre\'de Milletler Cemiyeti Genel Kurulu\'na hitap ederek ülkesinin kaderinin bütün küçük devletleri ilgilendirdiğini söyleyen Habeş imparatoru kimdir?', 'Hayle Selasiye', ['II. Menelik', 'Lij İyasu', 'IV. Yohannes'], 'İmparatorun konuşması, kolektif güvenliğin çöküşünü simgeleyen anlardan biri oldu; Cemiyet birkaç gün sonra yaptırımları kaldırdı.'),
  ('İtalyan ordusunun 1935-1936 Habeşistan savaşında uluslararası hukuka aykırı olarak başvurduğu yöntem hangisidir?', 'Hardal gazı gibi kimyasal silahlar kullanmak', ['Nükleer silah denemek', 'Biyolojik silahlarla tarlaları zehirleyerek ülkede kıtlık yaratmak', 'Denizaltılarla Habeş donanmasını batırmak'], 'İtalya, 1925 Cenevre Protokolü\'ne taraf olmasına karşın hem askerlere hem sivillere karşı kimyasal silah kullandı.'),
  ('Habeşistan bunalımının savaşlar arası uluslararası düzen açısından en önemli sonucu hangisidir?', 'Kolektif güvenlik sisteminin itibarını yitirip İtalya\'nın Almanya\'ya yaklaşması', ['Milletler Cemiyeti\'nin gücünü artırıp İtalya\'yı cezalandırabilmesi', 'İngiltere ile İtalya\'nın Akdeniz\'de Almanya\'ya karşı kalıcı bir ittifak kurması', 'Habeşistan\'ın Milletler Cemiyeti\'nden ihraç edilmesi'], 'Bunalım, Cemiyet\'in büyük bir devleti durduramayacağını gösterdi; yaptırımlara öfkelenen Mussolini 1936\'da Hitler\'le yakınlaştı.'),
  ('Lenin\'in ölümünden önce kaleme aldığı ve Stalin\'in genel sekreterlikten alınmasını öneren notlar hangi adla bilinir?', 'Lenin\'in Vasiyeti', ['Nisan Tezleri', 'Ne Yapmalı?', 'Kızıl Kitap'], 'Lenin, Stalin\'i \'fazla kaba\' bulduğunu yazdı; ancak belge parti önderliğince geniş kitlelerden saklandı ve Stalin konumunu korudu.'),
  ('Stalin\'in \'tek ülkede sosyalizm\' görüşü, Troçki\'nin hangi görüşüne karşı geliştirilmiştir?', 'Devrimin dünyaya yayılması gerektiğini savunan sürekli devrim anlayışına', ['Köylülüğün devrimin asıl öncüsü olduğunu ve işçi sınıfının ikincil kaldığını savunan narodnik görüşe', 'Çarlığın anayasal monarşiye dönüştürülmesi önerisine', 'Pazar ekonomisine tümüyle geri dönülmesi önerisine'], 'Stalin, SSCB\'nin önce kendi gücüyle sosyalizmi kurabileceğini savundu; Troçki ise devrimin Batı\'ya yayılmadan yaşayamayacağını düşünüyordu.'),
  ('Sovyetler Birliği\'nde ağır sanayiyi hızla geliştirmeyi amaçlayan Birinci Beş Yıllık Plan hangi yıl başlamıştır?', '1928', ['1921', '1933', '1924'], 'Plan 1928\'de başladı ve dört yılda tamamlandığı ilan edildi; çelik, kömür ve makine üretiminde büyük artışlar sağlandı ancak tüketim malları ve yaşam koşulları geri planda kaldı.'),
  ('1935\'te bir vardiyada normun on katından fazla kömür çıkardığı bildirilen ve adı yüksek verimli işçi hareketine verilen Sovyet madenci kimdir?', 'Aleksey Stahanov', ['Pavlik Morozov', 'Nikolay Ostrovski', 'Trofim Lısenko'], 'Stahanovcu hareket propagandayla desteklendi; çalışma normları yükseltilerek diğer işçiler üzerindeki baskı da arttı.'),
  ('Stalin\'in kolektifleştirme sırasında \'sınıf olarak tasfiye edilmesini\' istediği görece varlıklı köylülere ne ad verilmiştir?', 'Kulak', ['Muzhik', 'Boyar', 'Kazak'], 'Kulak olarak damgalanan milyonlarca köylü topraklarından sürüldü, sürgüne gönderildi ya da öldürüldü; kavram zamanla direnen her köylüyü kapsar oldu.'),
  ('1932-1933\'te kolektifleştirme ve tahıl el koymalarının yol açtığı, Ukrayna\'da milyonlarca kişinin ölümüyle sonuçlanan kıtlık Ukrayna\'da hangi adla anılır?', 'Holodomor', ['Pogrom', 'Gulag', 'Yejovşçina'], 'Holodomor \'açlıkla öldürme\' anlamına gelir; kıtlık Kazakistan başta olmak üzere SSCB\'nin başka bölgelerini de vurdu.'),
  ('Kolektifleştirme döneminde SSCB\'de kurulan \'kolhoz\' ile \'sovhoz\' arasındaki temel fark nedir?', 'Kolhoz köylülerin ortak çiftliği, sovhoz ise ücretli işçilerin çalıştığı devlet çiftliğiydi', ['Kolhoz yalnız hayvancılık, sovhoz yalnız buğday üretiyordu', 'Kolhoz kentlerin çevresinde sanayiye bağlı, sovhoz ise uzak köylerde bağımsız kuruluyordu', 'Kolhoz özel mülk, sovhoz yabancı şirket mülküydü'], 'Kolhoz üyeleri ürünün devlete teslimatından sonra kalan paya göre gelir alırken sovhozlarda devlet işçilere ücret ödüyordu.'),
  ('1934\'te Sovyet Yazarlar Kongresi\'nde resmî sanat anlayışı olarak benimsenen ve sanatın sosyalizmin kuruluşunu iyimser biçimde yansıtmasını isteyen akım hangisidir?', 'Sosyalist gerçekçilik', ['Konstrüktivizm', 'Fütürizm', 'Süprematizm'], 'Sosyalist gerçekçilik deneysel akımların yerini aldı; sanatçılar partinin çizdiği sınırlar içinde üretmek zorunda kaldı.'),
  ('New York Borsası\'nda panik satışlarının başladığı 24 Ekim 1929 günü hangi adla anılır?', 'Kara Perşembe', ['Kara Pazartesi', 'Kara Cuma', 'Kara Çarşamba'], 'Kara Perşembe\'yi 29 Ekim\'deki Kara Salı izledi; birkaç gün içinde hisse senetleri değerlerinin büyük bölümünü yitirdi.'),
  ('1920\'lerin sonunda ABD\'de hisse senetlerinin fiyatın küçük bir kısmı peşin, kalanı borçla alınması uygulaması borsa çöküşünü nasıl ağırlaştırmıştır?', 'Fiyatlar düşünce borçlu yatırımcıların zorunlu satışları düşüşü daha da hızlandırdı', ['Yatırımcıların hiçbir kayıp yaşamamasını sağladı', 'Bankaların batmasını tümüyle engelledi', 'Fiyatların devlet güvencesi sayesinde çöküş sırasında bile uzun süre sabit kalmasına yol açtı'], 'Kredili alımda fiyat düşünce aracılar ek teminat istedi; ödeyemeyenlerin hisseleri satılınca çöküş kendi kendini besledi.'),
  ('İngiltere, Büyük Buhran sırasında sterlin üzerindeki baskı nedeniyle hangi yıl altın standardını terk etmiştir?', '1931', ['1925', '1929', '1936'], 'Eylül 1931\'de altın standardından çıkılması sterlinin değer kaybetmesine ama İngiliz ekonomisinin görece daha erken toparlanmasına olanak verdi.'),
  ('ABD\'de Büyük Buhran yıllarında işsizlerin kent kenarlarında kurduğu derme çatma barınaklardan oluşan mahallelere hangi ad verilmiştir?', 'Hoovervilles', ['Rooseveltburgs', 'Gecekondu Kentleri', 'Kızıl Mahalleler'], 'Ad, bunalıma yeterli devlet müdahalesiyle karşılık vermediği düşünülen Başkan Herbert Hoover\'a yönelik alaycı bir göndermeydi.'),
  ('1930\'larda ABD\'nin Büyük Ovalar bölgesinde kuraklık ve yanlış tarım yöntemleri sonucu toprağın toz fırtınalarıyla savrulmasıyla oluşan felaket hangi adla bilinir?', 'Toz Çanağı', ['Kum Kuşağı', 'Kara Ova', 'Kuru Vadi'], 'Toz Çanağı yüz binlerce çiftçi ailesini Kaliforniya\'ya göçe zorladı; John Steinbeck\'in \'Gazap Üzümleri\' bu göçü anlatır.'),
  ('Bunalım dönemlerinde devletin harcamaları artırarak toplam talebi canlandırması gerektiğini savunan \'İstihdam, Faiz ve Paranın Genel Teorisi\' 1936\'da kim tarafından yayımlanmıştır?', 'John Maynard Keynes', ['Milton Friedman', 'Joseph Schumpeter', 'Alfred Marshall'], 'Keynes\'in görüşleri bunalımın kendiliğinden düzelmeyeceğini savunarak devlet müdahalesine kuramsal temel sağladı.'),
  ('Franklin D. Roosevelt\'in Mart 1933\'teki göreve başlama konuşmasında yer alan ve bunalım karşısında paniği yatıştırmayı amaçlayan ünlü cümle hangisidir?', 'Korkmamız gereken tek şey korkunun kendisidir.', ['Ülkenin sizin için ne yapabileceğini sormayın.', 'Önümüzde kan, ter ve gözyaşından başka bir şey yok.', 'Halkın, halk tarafından, halk için yönetimi.'], 'Roosevelt bu sözle bankalara hücum eden halkın güvenini yeniden kazanmayı hedefledi. Diğer sözler Kennedy, Churchill ve Lincoln\'e aittir.'),
  ('Roosevelt\'in radyo aracılığıyla halka doğrudan seslenerek bankacılık ve ekonomi politikalarını sade bir dille açıkladığı konuşmalara ne ad verilir?', 'Şömine başı sohbetleri', ['Beyaz Saray brifingleri', 'Basın toplantıları', 'Ulusa sesleniş mektupları'], 'Bu konuşmalar radyonun siyasal iletişimdeki gücünü gösterdi; ilk sohbet 1933 banka tatilinden sonra mevduatların güvende olduğunu anlatıyordu.'),
  ('New Deal kapsamında 1933\'te kurulan ve Tennessee Nehri havzasında barajlar inşa ederek bölgeye elektrik götüren kamu kuruluşu hangisidir?', 'Tennessee Vadisi İdaresi (TVA)', ['Sivil Koruma Birlikleri (CCC)', 'Çalışma Projeleri İdaresi (WPA)', 'Ulusal Kalkınma İdaresi (NRA)'], 'TVA, ABD\'nin en yoksul bölgelerinden birinde sel kontrolü, elektrik üretimi ve kalkınmayı birlikte yürüten bir devlet girişimiydi.'),
  ('New Deal programı olan Sivil Koruma Birlikleri (CCC) hangi kesime iş sağlamayı amaçlamıştır?', 'İşsiz genç erkeklere ormancılık ve doğa koruma işlerinde', ['Yaşlılara emeklilik maaşı bağlayarak', 'Çiftçilere üretimi azaltma karşılığı ödeme yaparak', 'Çiftçilere ekili alanı azaltmaları karşılığında doğrudan ödeme yaparak tarımı desteklemeye'], 'CCC gençleri kamplarda barındırarak ağaç dikimi, erozyon önleme ve park yapımında çalıştırdı; ücretlerin bir bölümü ailelerine gönderiliyordu.'),
  ('1935\'te kabul edilen ve ABD\'de yaşlılık aylığı ile işsizlik sigortasının temelini atan yasa hangisidir?', 'Sosyal Güvenlik Yasası', ['Wagner Yasası', 'Glass-Steagall Yasası', 'Taft-Hartley Yasası'], 'Sosyal Güvenlik Yasası, ABD\'de federal düzeyde refah devleti uygulamalarının başlangıcı sayılır.'),
  ('ABD Yüksek Mahkemesi\'nin 1935\'te Ulusal Sanayi Kalkınma Yasası\'nı (NIRA) anayasaya aykırı bulmasının gerekçesi aşağıdakilerden hangisidir?', 'Federal yönetimin eyaletler içi ticareti düzenleyerek yetkisini aşması', ['Yasanın işçilere grev ve sendika kurma hakkı tanımayarak temel özgürlükleri çiğnemesi', 'Yasanın yalnızca yabancı şirketlere uygulanması', 'Yasanın gümrük vergilerini kaldırması'], 'Schechter davasında mahkeme, yasanın eyaletler arası ticaret yetkisini aştığına ve yasama yetkisini yürütmeye aşırı devrettiğine hükmetti.'),
  ('ABD Kongresi\'nin 1935-1937 arasında çıkardığı Tarafsızlık Yasaları hangi kaygıyı yansıtır?', 'ABD\'nin yeni bir Avrupa savaşına sürüklenmesini önleme isteğini', ['ABD\'nin Avrupa\'daki karışıklıktan yararlanarak Afrika\'da sömürge edinme isteğini', 'Sovyetler Birliği\'yle ittifak kurma isteğini', 'Japonya\'ya karşı önleyici savaş isteğini'], 'Yasalar savaşan taraflara silah satışını ve kredi verilmesini kısıtladı; I. Dünya Savaşı\'na girişin silah tüccarları ve bankerlerce sağlandığı görüşü yaygındı.'),
  ('ABD\'de alkollü içkilerin üretimini, satışını ve taşınmasını yasaklayan ve 1920\'de yürürlüğe giren anayasa değişikliği hangisidir?', 'On sekizinci değişiklik', ['On dokuzuncu değişiklik', 'Yirmi birinci değişiklik', 'On altıncı değişiklik'], 'İçki yasağını getiren 18. değişiklik 1933\'te 21. değişiklikle kaldırıldı. 19. değişiklik ise kadınlara oy hakkı veren düzenlemedir.'),
  ('ABD\'de 1920-1933 içki yasağı döneminin beklenmeyen sonuçlarından biri aşağıdakilerden hangisidir?', 'Kaçakçılık üzerinden örgütlü suç çetelerinin güçlenmesi', ['Alkol tüketiminin tamamen sona ermesi', 'Federal hükümetin vergi gelirlerinin artması', 'Kilise bağışlarının ve fabrika üretiminin keskin biçimde artması'], 'Gizli barlar ve kaçak içki ticareti Al Capone gibi çete liderlerini zenginleştirdi; yolsuzluk ve şiddet arttı, devlet vergi gelirinden yoksun kaldı.'),
  ('İçki yasağı döneminde Chicago\'daki örgütlü suçun simgesi olan ve sonunda vergi kaçakçılığından mahkûm edilen çete lideri kimdir?', 'Al Capone', ['Lucky Luciano', 'John Dillinger', 'Bugsy Siegel'], 'İçki yasağını getiren 18. değişiklik 1933\'te 21. değişiklikle kaldırıldı; yasak dönemi bu nedenle on üç yıl sürdü.'),
  ('ABD anayasasına 1920\'de eklenen ve cinsiyete dayalı oy kısıtlamasını yasaklayan değişiklik hangisidir?', 'On dokuzuncu değişiklik', ['On beşinci değişiklik', 'On sekizinci değişiklik', 'Yirminci değişiklik'], '19. değişiklik kadınlara federal düzeyde oy hakkı tanıdı; uzun süren süfrajet mücadelesinin ürünüdür.'),
  ('Henry Ford\'un 1913\'te Model T üretiminde hareketli montaj bandını kullanmaya başlamasının ekonomik sonucu nedir?', 'Üretim süresi ve maliyet düştüğü için otomobilin geniş kitlelere ulaşması', ['Otomobillerin yalnız zenginlere özel ve el yapımı lüks bir tüketim malına dönüşmesi', 'İşçi sayısının artıp ücretlerin düşmesi', 'Otomobil üretiminin Avrupa\'ya kayması'], 'Bant sistemiyle bir Model T\'nin üretim süresi saatlere indi, fiyatı düştü; 1920\'lerde otomobil Amerikan orta sınıfının sıradan bir malı oldu.'),
  ('1927\'de New York\'tan Paris\'e tek başına ve aralıksız uçarak Atlantik\'i geçen ilk pilot kimdir?', 'Charles Lindbergh', ['Amelia Earhart', 'Wilbur Wright', 'Howard Hughes'], 'Lindbergh\'in \'Spirit of St. Louis\' adlı uçakla yaptığı yaklaşık 33,5 saatlik uçuş onu dünya çapında üne kavuşturdu.'),
  ('1919-1920 yıllarında ABD\'de grev dalgası ve bombalı saldırılar sonrasında komünist ve anarşist olduğundan şüphelenilen göçmenlere yönelik baskı dönemi hangi adla anılır?', 'Kızıl Korku', ['Mccarthycilik', 'Kara Liste Dönemi', 'Büyük Sürgün'], 'Başsavcı Palmer\'ın baskınlarında binlerce kişi tutuklandı ve yüzlercesi sınır dışı edildi; McCarthycilik ise 1950\'lerdeki ikinci Kızıl Korku\'dur.'),
  ('F. Scott Fitzgerald\'ın 1920\'lerin zengin ve eğlence düşkünü yaşamını eleştirel bir gözle anlattığı 1925 tarihli romanı hangisidir?', 'Muhteşem Gatsby', ['Gazap Üzümleri', 'Silahlara Veda', 'Fareler ve İnsanlar'], 'Fitzgerald dönemi adlandıran \'Caz Çağı\' ifadesini de yaygınlaştırdı.'),
  ('1920\'lerde New York\'un bir semtinde Afro-Amerikan müzik, edebiyat ve sanatında yaşanan canlanma hangi adla anılır?', 'Harlem Rönesansı', ['Brooklyn Uyanışı', 'Chicago Okulu', 'Güney Rönesansı'], 'Langston Hughes, Zora Neale Hurston ve Duke Ellington gibi isimler bu dönemde öne çıktı; hareket siyah kimliğinin kültürel ifadesini güçlendirdi.'),
  ('Nisan 1916\'da Dublin\'de İrlandalı milliyetçilerin bağımsız bir cumhuriyet ilan ederek başlattığı ve bir haftada bastırılan ayaklanma hangi adla anılır?', 'Paskalya Ayaklanması', ['Kanlı Pazar', 'Dublin Komünü', 'Yeşil İsyan'], 'Ayaklanma başta halktan az destek gördü; ancak önderlerinin kurşuna dizilmesi kamuoyunu İngiltere\'ye karşı çevirdi ve cumhuriyetçi hareketi güçlendirdi.'),
  ('Paskalya Ayaklanması\'nın bastırılmasından sonra İngiltere\'nin ayaklanma önderlerini idam etmesi İrlanda siyasetini nasıl etkilemiştir?', 'Ilımlı özerklik yanlılarının zemin kaybedip Sinn Féin\'in 1918 seçimlerinde büyük zafer kazanması', ['İrlandalıların bağımsızlık isteğinden tamamen vazgeçmesi', 'İrlanda\'nın İngiliz parlamentosunun kararıyla hemen tam bağımsızlığını kazanması ve adanın birleşmesi', 'İrlandalı milliyetçilerin İngiliz ordusuna toplu katılımı'], '1918 seçimlerinde Sinn Féin İrlanda sandalyelerinin büyük çoğunluğunu kazandı, Westminster\'e gitmeyip Dublin\'de kendi meclisini (Dáil) kurdu.'),
  ('Aralık 1921\'de imzalanan İngiliz-İrlanda Antlaşması ile kurulan devletin statüsü nedir?', 'İngiliz Milletler Topluluğu içinde dominyon statüsünde İrlanda Özgür Devleti', ['Kuzey dâhil bütün adayı kapsayan, krala bağlılık yemini içermeyen tam bağımsız İrlanda Cumhuriyeti', 'İngiltere\'ye bağlı özerk bir eyalet', 'Fransa himayesinde bir krallık'], 'Antlaşma kuzeydeki altı kontluğun Birleşik Krallık\'ta kalmasına olanak verdi; krala bağlılık yemini ve bölünme, İrlanda İç Savaşı\'na yol açtı.'),
  ('İngiltere\'de 1918 Halkın Temsili Yasası ile kadınlara oy hakkı tanınırken kadınlar için konulan yaş sınırı neydi?', '30', ['18', '21', '25'], '1918\'de erkeklerde yaş sınırı 21 iken kadınlar için 30 yaş ve bazı mülkiyet koşulları getirildi; eşitlik ancak 1928\'de 21 yaşla sağlandı.'),
  ('İngiltere\'de Mayıs 1926\'da dokuz gün süren Genel Grev\'in çıkış nedeni nedir?', 'Kömür madencilerinin ücret indirimi ve çalışma saatlerinin uzatılmasına karşı desteklenmesi', ['Kadınların oy hakkı talebi', 'Kolonilerin bağımsızlık talebine verilen destek', 'Zorunlu askerliğin yeniden getirilmesine tepki'], 'Sendikalar Kongresi madencilere destek için genel grev çağrısı yaptı; hükümetin direnişi karşısında grev dokuz gün sonra sonuçsuz bitti.'),
  ('Aralık 1936\'da iki kez boşanmış bir Amerikalıyla evlenmek için tahtı bırakan İngiliz kralı kimdir?', 'VIII. Edward', ['V. George', 'VI. George', 'VII. Edward'], 'Kral ile Wallis Simpson\'ın evliliği hükümet ve kilise tarafından kabul edilmedi; taht kardeşi VI. George\'a geçti.'),
  ('1936\'da kuzeydoğu İngiltere\'de bir tersane kentinden yaklaşık iki yüz işsizin Londra\'ya yürüyerek hükümetten iş istediği protesto hangi kentin adıyla anılır?', 'Jarrow', ['Manchester', 'Liverpool', 'Sheffield'], 'Tersanesinin kapanmasıyla işsizliğin çok yükseldiği Jarrow\'un yürüyüşü, bunalımda bölgesel eşitsizliklerin simgesi oldu.'),
  ('Fransa\'nın 1930\'larda Alman sınırı boyunca inşa ettiği Maginot Hattı\'nın temel stratejik zayıflığı neydi?', 'Belçika sınırı ve Ardenler boyunca uzanmaması', ['Yalnızca İtalya sınırında kurulmuş olması', 'Tamamen ahşaptan yapılmış olması', 'Almanya\'ya saldırı amacıyla tasarlanmış olması'], 'Hat, savunma anlayışıyla Alman sınırını korudu; ancak müttefik Belçika ile sınır ve ormanlık Ardenler aynı ölçüde tahkim edilmedi.'),
  ('Maginot Hattı\'nın inşası Fransa\'nın savaşlar arası askerî anlayışı hakkında neyi gösterir?', 'I. Dünya Savaşı deneyimine dayalı savunmacı bir strateji benimsediğini', ['Hızlı ve derin tank saldırılarına dayalı yeni bir hareket savaşı doktrini geliştirdiğini', 'Almanya\'yı önleyici savaşla işgal etmeyi planladığını', 'Ordusunu tümüyle hava kuvvetlerine dönüştürdüğünü'], 'Siper savaşının ağır kayıplarından ders çıkaran Fransız komutanlığı güçlü tahkimatlara güvendi; bu anlayış Doğu Avrupa\'daki müttefiklerine yardım etme kapasitesini de sınırladı.'),
  ('1936\'da Fransa\'da Halk Cephesi hükümetini kuran ve ülkenin ilk sosyalist başbakanı olan siyasetçi kimdir?', 'Léon Blum', ['Édouard Daladier', 'Pierre Laval', 'Paul Reynaud'], 'Blum hükümeti sosyalistler, radikaller ve komünistlerin dışarıdan desteğiyle kuruldu.'),
  ('Fransa\'da 1936 Halk Cephesi döneminde kabul edilen düzenlemeler arasında aşağıdakilerden hangisi yer almaz?', 'Zorunlu askerlik süresinin kaldırılması', ['Haftalık çalışma süresinin 40 saatle sınırlanması', 'İşçilere yıllık ücretli izin hakkı verilmesi', 'Toplu sözleşme hakkının tanınması'], 'Matignon Anlaşmaları ve ardından gelen yasalar ücret artışı, toplu sözleşme, 40 saatlik çalışma haftası ve iki hafta ücretli izin getirdi; askerlik ise kaldırılmadı.'),
  ('İspanya\'da 1931 yerel seçimlerinde cumhuriyetçilerin büyük kentlerde kazanmasının ardından hangi gelişme yaşanmıştır?', 'Kral XIII. Alfonso ülkeyi terk etti ve İkinci Cumhuriyet ilan edildi', ['Franco askerî darbeyle iktidara geldi', 'İspanya Milletler Cemiyeti\'nden çekildi', 'Katalonya ile Bask bölgesi birleşerek bağımsız bir krallık ilan etti'], 'Nisan 1931\'de kralın ayrılmasıyla İkinci İspanya Cumhuriyeti kuruldu; toprak reformu, kilise ve ordu konusundaki reformlar toplumu kutuplaştırdı.'),
  ('Temmuz 1936\'da İspanya Cumhuriyeti\'ne karşı başlayan askerî ayaklanma ilk olarak nerede patlak vermiştir?', 'İspanyol Fas\'ında', ['Madrid\'de', 'Barselona\'da', 'Bask bölgesinde'], 'Ayaklanma 17 Temmuz\'da İspanyol Fas\'ındaki birliklerle başladı ve ertesi gün anakaraya yayıldı.'),
  ('İspanya İç Savaşı\'nda Franco saflarında savaşan Alman hava birliği hangi adla anılır?', 'Kondor Lejyonu', ['Luftwaffe Akdeniz Filosu', 'Kara Kartal Birliği', 'Stuka Tümeni'], 'Kondor Lejyonu yeni uçak ve bombalama tekniklerini İspanya\'da denedi; Guernica bombardımanını bu birlik gerçekleştirdi.'),
  ('Nisan 1937\'de Bask bölgesinde bir kasabanın Alman ve İtalyan uçaklarınca bombalanmasını konu alan ünlü tabloyu yapan ressam kimdir?', 'Pablo Picasso', ['Salvador Dalí', 'Joan Miró', 'Francisco Goya'], 'Guernica tablosu 1937 Paris Uluslararası Sergisi\'nin İspanya pavyonu için yapıldı ve savaşın sivillere yönelik dehşetinin evrensel simgesi oldu.'),
  ('İspanya İç Savaşı\'nda dünyanın dört bir yanından Cumhuriyet\'i savunmak için gelen gönüllülerden oluşan birlikler hangi adla bilinir?', 'Uluslararası Tugaylar', ['Yabancı Lejyon', 'Barış Gücü', 'Kızıl Muhafızlar'], 'Uluslararası Tugaylar büyük ölçüde Komintern tarafından örgütlendi; on binlerce gönüllü özellikle Madrid savunmasında yer aldı.'),
  ('İspanya İç Savaşı sırasında kuşatılan Madrid\'in savunmasında Cumhuriyetçilerin kullandığı ve \'Geçemeyecekler\' anlamına gelen slogan hangisidir?', '¡No pasarán!', ['¡Viva la muerte!', '¡Arriba España!', '¡Venceremos!'], 'Slogan özellikle komünist milletvekili Dolores Ibárruri (\'La Pasionaria\') ile özdeşleşti. \'Arriba España\' ise milliyetçilerin sloganıydı.'),
  ('1919\'da Macaristan\'da birkaç ay süren Sovyet Cumhuriyeti\'ne önderlik eden komünist kimdir?', 'Béla Kun', ['Mihály Károlyi', 'István Bethlen', 'Gyula Gömbös'], 'Macar Sovyet Cumhuriyeti Mart-Ağustos 1919 arasında sürdü ve Romen ordusunun Budapeşte\'ye girmesiyle çöktü.'),
  ('Yugoslavya Kralı Aleksandar\'ın 6 Ocak 1929\'da anayasayı askıya alıp meclisi kapatmasının arka planında hangi sorun vardı?', 'Sırplar ile Hırvatlar arasındaki derin siyasi çatışma', ['Sovyetler Birliği\'nin Belgrad\'ı işgal edip komünist bir hükümet kurmaya çalışması', 'İtalya\'nın Yugoslavya\'ya savaş ilan etmesi', 'Kralın tahttan indirilmek istenmesi'], '1928\'de mecliste Hırvat Köylü Partisi önderi Stjepan Radić\'in vurulması bunalımı doruğa çıkardı; kral merkeziyetçi bir diktatörlük kurdu ve ülkenin adını Yugoslavya yaptı.'),
  ('Çekoslovakya, Romanya ve Yugoslavya\'nın 1920-1921\'de kurduğu Küçük İtilaf\'ın temel amacı neydi?', 'Macaristan\'ın toprak revizyonu ve Habsburg restorasyonu girişimlerine karşı ortak savunma', ['Sovyetler Birliği ile birleşerek Orta Avrupa\'da bir federal sosyalist cumhuriyet kurmak', 'Almanya\'yı Milletler Cemiyeti\'ne sokmak', 'Balkanlarda ortak bir para birimi kurmak'], 'Küçük İtilaf Fransa\'nın Orta Avrupa\'daki güvenlik sisteminin parçası oldu; ancak 1930\'larda Almanya\'nın yükselişi karşısında etkisini yitirdi.'),
  ('Aşağıdaki Orta ve Doğu Avrupa ülkelerinden hangisi savaşlar arası dönemde 1938\'e kadar demokratik parlamenter düzenini koruyabilmiştir?', 'Çekoslovakya', ['Polonya', 'Macaristan', 'Yugoslavya'], 'Masaryk ve Beneš önderliğindeki Çekoslovakya, bölgedeki otoriterleşme dalgasına karşın demokrasisini Münih Antlaşması\'na kadar sürdürdü.'),
  ('1936\'da İtalya ile Almanya arasında kurulan yakınlaşmayı Mussolini\'nin Avrupa\'nın çevresinde döneceği bir eksen olarak tanımlamasından doğan kavram hangisidir?', 'Mihver', ['İtilaf', 'Antant', 'Konsert'], 'Roma-Berlin Mihveri Kasım 1936\'da ilan edildi; ardından Japonya\'nın da katılımıyla Mihver Devletleri kavramı oluştu.'),
  ('Almanya ile Japonya\'nın Kasım 1936\'da imzaladığı ve İtalya\'nın 1937\'de katıldığı Anti-Komintern Paktı\'nın görünürdeki amacı neydi?', 'Uluslararası komünist faaliyetlere karşı iş birliği', ['Milletler Cemiyeti\'ni güçlendirmek', 'Çin\'in bağımsızlığını güvenceye almak', 'Balkanlar\'daki sınırları garanti altına almak'], 'Pakt Sovyetler Birliği\'ne ve Komintern\'e karşı yöneliyordu; gizli eki taraflardan birinin SSCB ile savaşı hâlinde ötekinin onu desteklemeyeceğini öngörüyordu.'),
  ('Çekoslovakya\'daki Südet Almanlarının Hitler\'le eş güdüm içinde özerklik ve ardından Almanya\'ya katılma taleplerini yönlendiren siyasetçi kimdir?', 'Konrad Henlein', ['Arthur Seyss-Inquart', 'Emil Hácha', 'Jozef Tiso'], 'Henlein\'in Südet Alman Partisi, Hitler\'in talimatıyla Prag hükümetinin kabul edemeyeceği talepler ileri sürerek bunalımı tırmandırdı.'),
  ('Eylül 1938 Münih Konferansı\'nda Çekoslovakya\'nın geleceği hakkında karar alınırken hangi durum dikkat çekicidir?', 'Çekoslovakya\'nın ve Sovyetler Birliği\'nin görüşmelere çağrılmaması', ['Almanya\'nın görüşmelere katılmaması', 'Kararların Cenevre\'de Milletler Cemiyeti Genel Kurulu\'nda oy birliğiyle alınması', 'Konferansın Prag\'da toplanması'], 'Hitler, Mussolini, Chamberlain ve Daladier, Çekoslovakya\'nın katılımı olmadan Südet bölgesinin Almanya\'ya verilmesine karar verdi.'),
  ('Münih\'ten dönerken imzalı bir belgeyi göstererek \'zamanımız için barış\' sağladığını söyleyen İngiliz başbakanı kimdir?', 'Neville Chamberlain', ['Stanley Baldwin', 'Winston Churchill', 'Anthony Eden'], 'Chamberlain\'ın Hitler\'le imzaladığı kısa bildiri iki ülkenin bir daha savaşmama isteğini dile getiriyordu; altı ay sonra Almanya Prag\'ı işgal etti.'),
  ('Almanya\'nın 15 Mart 1939\'da Prag\'ı işgal etmesi İngiltere\'nin politikasını neden kökten değiştirmiştir?', 'Hitler\'in hedeflerinin yalnızca Almanları birleştirmekle sınırlı olmadığını açıkça göstermesi', ['Prag\'ın İngiliz sömürgesi olması', 'Almanya\'nın aynı gün İngiltere\'ye savaş ilan etmesi', 'Çekoslovakya\'nın İngiltere ile 1925\'ten beri resmî bir ittifak antlaşmasıyla bağlı bulunması'], 'Alman olmayan bir halkın işgali yatıştırmanın gerekçesini çökertti; İngiltere 31 Mart 1939\'da Polonya\'ya bağımsızlık güvencesi verdi.'),
  ('Almanya ile İtalya\'nın Mayıs 1939\'da imzaladığı ve taraflardan biri savaşa girdiğinde ötekinin onu bütün gücüyle desteklemesini öngören askerî ittifak hangi adla bilinir?', 'Çelik Pakt', ['Demir Antlaşma', 'Üçlü Pakt', 'Roma Protokolü'], 'Çelik Pakt saldırı ya da savunma ayrımı yapmayan bir askerî ittifaktı; Japonya\'nın da katıldığı Üçlü Pakt ise Eylül 1940\'ta imzalandı.'),
  ('İngiltere ve Fransa\'nın 1930\'larda Hitler\'e karşı yatıştırma politikası izlemesinin nedenleri arasında aşağıdakilerden hangisi yer almaz?', 'Almanya ile resmî bir ittifak antlaşmasına bağlı olmaları', ['I. Dünya Savaşı\'nın yıkımının yarattığı savaş korkusu', 'Silahlanmada Almanya\'nın gerisinde kalmış olmaları ve yeniden silahlanmaya zaman gerekmesi', 'Versay\'ın Almanya\'ya fazla ağır davrandığı düşüncesi'], 'Savaş korkusu, ekonomik sıkıntı, silahlanma eksikliği ve Versay\'a dair suçluluk duygusu yatıştırmayı besledi; iki ülkenin Almanya ile bir ittifakı yoktu.'),
  ('1915-1916 yıllarında Mekke Şerifi Hüseyin ile İngiltere\'nin Mısır Yüksek Komiseri arasında yapılan yazışmaların temel içeriği nedir?', 'Osmanlı\'ya karşı ayaklanma karşılığında Araplara bağımsızlık sözü verilmesi', ['Arap topraklarının Fransa\'ya bırakılmasının kararlaştırılması', 'Arap topraklarının savaştan sonra Fransa\'nın doğrudan yönetimine bırakılmasının kararlaştırılması', 'Mısır\'ın İngiltere\'den bağımsızlığının tanınması'], 'Hüseyin-McMahon yazışmaları sınırları belirsiz bir Arap devleti vaat ediyordu; aynı dönemde yapılan gizli İngiliz-Fransız paylaşımıyla çelişmesi savaş sonrası Arap öfkesinin kaynaklarından oldu.'),
  ('1916\'da İngiltere ile Fransa arasında Orta Doğu\'daki Osmanlı topraklarını nüfuz alanlarına bölen gizli anlaşma hangisidir?', 'Sykes-Picot Anlaşması', ['San Remo Antlaşması', 'Londra Antlaşması', 'Saint-Jean-de-Maurienne Antlaşması'], 'Anlaşmaya göre Suriye ve Lübnan bölgesi Fransa\'ya, Irak\'ın güneyi ve Ürdün yönü İngiltere\'ye düşüyordu; Filistin için uluslararası yönetim öngörülmüştü.'),
  ('Arap İsyanı\'nda Şerif Hüseyin\'in oğlu Faysal\'ın kuvvetleriyle birlikte çalışan ve sonradan \'Arabistanlı\' lakabıyla efsaneleşen İngiliz subay kimdir?', 'T. E. Lawrence', ['Edmund Allenby', 'Gertrude Bell', 'Herbert Kitchener'], 'Lawrence demiryolu baskınları gibi gerilla eylemlerini yönlendirdi; anılarını \'Bilgeliğin Yedi Sütunu\' adlı kitapta anlattı.'),
  ('Nisan 1920\'de toplanan ve Orta Doğu\'daki manda paylaşımını, Suriye ile Lübnan\'ı Fransa\'ya, Irak ile Filistin\'i İngiltere\'ye vererek kesinleştiren konferans hangisidir?', 'San Remo Konferansı', ['Lozan Konferansı', 'Kahire Konferansı', 'Cenevre Konferansı'], 'San Remo kararları Milletler Cemiyeti tarafından 1922-1923\'te manda belgeleriyle resmîleştirildi.'),
  ('İngiltere\'nin Şubat 1922\'de Mısır\'ın bağımsızlığını tek taraflı olarak tanırken bazı konuları kendi denetiminde tutmasının anlamı nedir?', 'Mısır\'ın resmî bağımsızlığına karşın İngiliz nüfuzunun Süveyş ve savunmada sürmesi', ['Mısır\'ın tümüyle Fransız mandasına geçmesi', 'Mısır\'ın Osmanlı\'ya yeniden bağlanması', 'Mısır\'da İngiliz askerlerinin hemen ve tamamen çekilip Süveyş\'in Mısır\'a devredilmesi'], 'İngiltere Süveyş Kanalı\'nın güvenliği, savunma, yabancıların korunması ve Sudan konularını kendine sakladı; bu sınırlı bağımsızlık milliyetçi muhalefeti sürdürdü.'),
  ('1932\'de Hicaz ve Necid\'i birleştirerek kendi hanedanının adını taşıyan krallığı ilan eden lider kimdir?', 'Abdülaziz İbn Suud', ['Şerif Hüseyin', 'Kral Abdullah', 'İmam Yahya'], 'İbn Suud 1920\'lerde Hicaz\'ı Haşimilerden aldı; Suudi Arabistan Krallığı 1932\'de bu adla ilan edildi.'),
  ('Eylül 1931\'de Japon Kwantung Ordusu\'nun Mukden yakınlarında kendi kontrolündeki demiryolunu havaya uçurup suçu Çinlilere atması hangi amaca hizmet etmiştir?', 'Mançurya\'nın işgali için bahane yaratmak', ['Çin ile barış antlaşması imzalamak', 'ABD\'yi savaşa sokmak', 'Sovyetler Birliği\'nin Uzak Doğu topraklarına saldırmak için gerekçe oluşturmak'], 'Mukden olayı, Japon ordusunun Tokyo hükümetinden de bağımsız davranarak Mançurya\'yı ele geçirmesinin başlangıcı oldu.'),
  ('Japonya\'nın 1932\'de Mançurya\'da kurduğu kukla devletin başına getirdiği, Çin\'in son Qing imparatoru kimdir?', 'Pu Yi', ['Yuan Shikai', 'Guangxu', 'Sun Yat-sen'], 'Pu Yi önce \'yönetici\', 1934\'te Mançukuo imparatoru ilan edildi; ancak gerçek yetki Japon ordusundaydı.'),
  ('Temmuz 1937\'de Pekin yakınlarında Japon ve Çin birlikleri arasında çıkan ve Çin-Japon Savaşı\'nı başlatan çatışma hangi adla anılır?', 'Marco Polo Köprüsü Olayı', ['Mukden Olayı', 'Tanggu Olayı', 'Şanghay Olayı'], 'Lugou Köprüsü olarak da bilinen yerdeki çatışma hızla topyekûn bir savaşa dönüştü.'),
  ('Aralık 1937\'de Japon ordusunun Çin\'in o dönemki başkentini ele geçirdikten sonra siviller ve esirlere karşı giriştiği kitlesel katliam hangi kentin adıyla anılır?', 'Nankin', ['Pekin', 'Vuhan', 'Kanton'], 'Nankin Katliamı\'nda haftalar boyunca on binlerce, bazı kaynaklara göre yüz binlerce sivil ve esir öldürüldü; olay Japon savaş suçlarının simgesi oldu.'),
  ('1918-1920 yıllarında dünyayı saran grip salgınının \'İspanyol gribi\' diye anılmasının nedeni nedir?', 'Tarafsız İspanya\'da basın sansürü olmadığından salgın haberlerinin ilk orada yaygınca yayılması', ['Salgının kesin olarak İspanya\'da başladığının kanıtlanması', 'İspanyol askerlerinin Batı Cephesi\'ne gönderilip hastalığı siperlere taşıması', 'İspanya\'nın aşıyı ilk bulan ülke olması'], 'Savaşan ülkeler moral bozmamak için haberleri sansürlüyordu; İspanyol basını ise salgını ve kralın hastalanmasını açıkça yazdı.'),
  ('1918 grip salgınının olağan grip salgınlarından ayrılan dikkat çekici özelliği nedir?', 'Ölümlerin yaşlılar kadar genç ve sağlıklı yetişkinlerde de çok yüksek olması', ['Yalnızca çocukları etkilemesi', 'Yalnızca Avrupa\'da görülmesi', 'Ölümlerin neredeyse tümünün yalnızca seksen yaş üstü yaşlılarda görülmesi'], 'Salgın özellikle 20-40 yaş arasında yüksek ölüm oranına yol açtı; cephe koşulları ve asker hareketleri yayılmayı hızlandırdı.'),
  ('Kanadalı asker hekim John McCrae\'nin Flandre\'daki mezarlar üzerine yazdığı ve gelinciği savaş anmalarının simgesi yapan şiir hangisidir?', 'Flandre Tarlalarında', ['Ölüm Tarlası', 'Somme Ağıtı', 'Kayıp Kuşak'], '\'In Flanders Fields\' şiiri 1915\'te yazıldı; gelincik kırmızısı İngiliz Milletler Topluluğu ülkelerinde anma sembolü oldu.'),
  ('11 Kasım 1920\'de Londra\'da Westminster Manastırı\'na, Paris\'te Zafer Takı\'nın altına kimliği belirlenemeyen birer askerin gömülmesi hangi düşünceyi yansıtır?', 'Adı bilinmeyen bütün kayıpları tek bir mezarda ortak olarak anmak', ['Savaşın en yüksek rütbeli subayını devlet töreniyle onurlandırıp anıtlaştırmak', 'Savaşı başlatan suçluları cezalandırmak', 'Yalnız soylu ailelerin şehitlerini anmak'], 'Meçhul Asker mezarları milyonlarca kaybın mezarı olmayan aileleri için ortak bir yas mekânı yarattı; uygulama sonra pek çok ülkeye yayıldı.'),
  ('Gertrude Stein\'ın ifadesiyle \'kayıp kuşak\' kavramı neyi anlatır?', 'Savaş deneyimiyle değerlerini yitirip yönünü kaybetmiş genç kuşağı', ['Savaşta ölen bütün askerleri', 'Savaş yıllarında doğan çocukları', 'Savaştan sonra Avrupa\'dan Amerika\'ya göç eden asker aileleri ve çocukları'], 'Hemingway\'in \'Güneş de Doğar\' romanının başına koyduğu bu ifade, 1920\'lerde kendini Paris\'te bulan Amerikalı yazarları ve savaş sonrası kuşağın ruh hâlini tanımlar.'),
  ('Romanya\'nın Ağustos 1916\'da İtilaf safında savaşa girmesinden sonraki birkaç ay içinde yaşanan gelişme hangisidir?', 'Alman, Avusturya, Bulgar ve Osmanlı kuvvetlerinin Bükreş\'i ele geçirmesi', ['Romen ordusunun Karpatlar\'ı aşıp Macar ovasını geçerek Budapeşte\'ye girmesi', 'Romanya\'nın Transilvanya\'yı kalıcı olarak alması', 'Bulgaristan\'ın teslim olması'], 'Romanya Transilvanya\'ya ilerledi ama Falkenhayn ve Mackensen\'in karşı saldırısıyla Aralık 1916\'da başkentini kaybetti; ordu kuzeydoğuda Moldova\'da tutunabildi.'),
  ('I. Dünya Savaşı boyunca tarafsızlığını koruyan Avrupa ülkeleri arasında aşağıdakilerden hangisi yoktur?', 'Belçika', ['İsviçre', 'İspanya', 'Hollanda'], 'Belçika tarafsızdı ama Almanya\'nın işgaliyle savaşa çekildi; İsviçre, İspanya, Hollanda ve İskandinav ülkeleri savaş dışı kaldı.'),
  ('Haber-Bosch amonyak sentezi yöntemi, abluka altındaki Almanya\'nın savaşı sürdürebilmesi açısından neden önemliydi?', 'Doğal güherçile ithal edemeyen Almanya\'nın patlayıcı ve gübre için azot elde etmesini sağladığı için', ['Almanya\'ya kömürden sentetik petrol ve uçak yakıtı üretme olanağını ilk kez verdiği için', 'Zehirli gaz kullanımını gereksiz kıldığı için', 'Denizaltıların menzilini artırdığı için'], 'Şili güherçilesi ablukayla kesilince yapay amonyak, mühimmat üretiminin sürmesinde hayati rol oynadı.'),
  ('Siper savaşında makineli tüfeğin savunmaya sağladığı üstünlük en iyi nasıl açıklanır?', 'Az sayıda askerin açık arazide ilerleyen çok sayıda piyadeyi durdurabilmesi', ['Tüfeklerin yalnız gece kullanılabilmesi', 'Makineli tüfeklerin uçaklardan atılabilmesi', 'Makineli tüfeklerin yalnızca süvari birliklerince kullanılabilmesi'], 'Tek bir makineli tüfek ekibi dakikada yüzlerce mermi atabiliyordu; tel örgülerle birleşince taarruz eden birlikler için ölümcül bir engel oluşturdu.'),
  ('Savaşın başında İngiliz Savaş Bakanı olan, \'Ülkenin sana ihtiyacı var\' afişleriyle simgeleşen ve 1916\'da bindiği geminin batmasıyla ölen mareşal kimdir?', 'Lord Kitchener', ['Douglas Haig', 'John French', 'Herbert Asquith'], 'Kitchener\'in gönüllü çağrısı milyonlarca İngiliz\'i orduya çekti; Haziran 1916\'da Rusya\'ya giderken HMS Hampshire\'ın mayına çarpmasıyla öldü.'),
  ('Aralık 1916\'da Asquith\'in yerine İngiltere başbakanı olan ve savaşı zaferle sonuçlandıran koalisyon hükümetini yöneten siyasetçi kimdir?', 'David Lloyd George', ['Bonar Law', 'Winston Churchill', 'Arthur Balfour'], 'Lloyd George küçük bir savaş kabinesiyle karar süreçlerini hızlandırdı; Paris Barış Konferansı\'nda da İngiltere\'yi temsil etti.'),
  ('ABD\'de savaşa katılımın ardından 1917\'de kurulan ve afişler, broşürler ve konuşmacılar aracılığıyla savaş propagandasını yürüten kurul hangisidir?', 'Kamu Bilgilendirme Komitesi', ['Savaş Endüstrileri Kurulu', 'Federal Soruşturma Bürosu', 'Ulusal Savunma Konseyi'], 'George Creel\'in yönettiği komite \'dört dakika adamları\' denen gönüllü konuşmacılarla kamuoyunu savaş için seferber etti.'),
  ('Almanya\'nın 1916\'da Manş\'ta bir Fransız yolcu gemisinin torpillenmesinden sonra ABD\'ye verdiği \'Sussex güvencesi\' neyi taahhüt ediyordu?', 'Yolcu ve ticaret gemilerini uyarmadan batırmamayı', ['ABD\'ye savaş tazminatı ödemeyi', 'Bütün denizaltılarını teslim etmeyi', 'Meksika ile ittifak görüşmelerinden vazgeçip Amerika kıtasından elini çekmeyi'], 'Almanya\'nın bu güvenceyi Şubat 1917\'de sınırsız denizaltı savaşıyla bozması, ABD\'nin savaşa girmesinin başlıca nedenlerinden oldu.'),
  ('ABD\'nin 1917\'de savaşa girdiği anda büyük bir orduya sahip olmamasına rağmen bir yıl içinde Fransa\'ya bir milyondan fazla asker gönderebilmesi neyi gösterir?', 'Zorunlu askerlik ve sanayi kapasitesiyle insan gücünü hızla seferber edebildiğini', ['Avrupa\'da önceden büyük askerî üsleri bulunduğunu', 'İngiltere\'nin kendi askerlerinin bir bölümünü Amerikan bayrağı ve komutası altına vermiş olduğunu', 'Almanya\'nın Amerikan gemilerine dokunmadığını'], 'Seçmeli Hizmet Yasası ile milyonlarca kişi kaydedildi; konvoy sistemi sayesinde asker taşımacılığında kayıplar çok düşük kaldı.'),
  ('Kimyasal ve biyolojik silahların savaşta kullanılmasını yasaklayan 1925 tarihli uluslararası belge hangisidir?', 'Cenevre Protokolü', ['Lahey Sözleşmesi', 'Locarno Senedi', 'Briand Memorandumu'], 'Protokol I. Dünya Savaşı\'ndaki gaz deneyiminin ardından imzalandı; kullanımı yasaklasa da üretimini ve stoklanmasını yasaklamıyordu.'),
  ('ABD Başkanı Hoover\'ın Haziran 1931\'de ilan ettiği moratoryum neyi öngörüyordu?', 'Savaş borçları ve tazminat ödemelerinin bir yıl süreyle askıya alınmasını', ['ABD\'nin Avrupa mallarına uyguladığı bütün gümrük vergilerini süresiz olarak kaldırmasını', 'Avrupa\'ya karşılıksız gıda yardımı yapılmasını', 'Doların altına bağlılığının kaldırılmasını'], 'Orta Avrupa bankacılık bunalımı üzerine ilan edilen bir yıllık erteleme, borç-tazminat zincirinin sürdürülemezliğini kabul ediyordu.'),
  ('Ocak 1924\'te Lenin\'in ölümünün ardından Petrograd\'ın aldığı yeni ad hangisidir?', 'Leningrad', ['Stalingrad', 'Sverdlovsk', 'Kirov'], 'Kentin adı 1991\'deki halkoylamasıyla yeniden Sankt-Peterburg oldu. Stalingrad ise Volga üzerindeki Çaritsin\'in 1925\'te aldığı addır.'),
  ('Yeni Ekonomik Politika döneminde küçük ticaretle zenginleşen tüccar ve aracılara verilen ve Bolşevik çevrelerde olumsuz anlam taşıyan ad hangisidir?', 'Nepmen', ['Kulak', 'Nomenklatura', 'Stahanovcu'], 'Nepmenler serbest piyasanın sınırlı ölçüde geri dönmesinin simgesiydi; NEP\'in 1928\'den sonra terk edilmesiyle tasfiye edildiler.'),
  ('Birinci Beş Yıllık Plan döneminde Ural Dağları\'nın güneyinde neredeyse sıfırdan kurulan ve dev çelik tesisiyle Sovyet sanayileşmesinin simgesi olan kent hangisidir?', 'Magnitogorsk', ['Volgograd', 'Novosibirsk', 'Murmansk'], 'Magnitogorsk, Amerikan modellerine göre tasarlanmış dev demir-çelik kombinasıyla kuruldu; inşaatında zorunlu çalıştırılan sürgünler de vardı.'),
  ('1936 Sovyet Anayasası\'nın kâğıt üzerindeki özellikleri ile dönemin uygulaması karşılaştırıldığında hangi yargıya varılır?', 'Geniş hak ve özgürlükler tanıdığı hâlde aynı yıllarda kitlesel terör uygulandı', ['Anayasa çok partili seçimleri güvenceye aldı ve bu seçimler 1937\'de serbestçe uygulandı', 'Anayasa Stalin\'in yetkilerini sınırlayıp onu görevden aldı', 'Anayasa SSCB\'yi bir monarşiye dönüştürdü'], '\'Stalin Anayasası\' dünyanın en demokratik anayasası diye tanıtıldı; ancak Büyük Terör aynı dönemde yaşandı ve tek parti egemenliği sürdü.'),
  ('Faşist İtalya\'da çocukları ve gençleri ideolojik ve askerî eğitimle rejime bağlamak için kurulan örgüt hangisidir?', 'Opera Nazionale Balilla', ['Hitler Gençliği', 'Komsomol', 'Kara Gömlekliler'], 'Balilla örgütü spor, tören ve askerî talimle gençleri faşizmin değerleriyle yetiştirmeyi amaçladı; adını 18. yüzyıl Cenovalı bir çocuk kahramandan alır.'),
  ('1936 Berlin Olimpiyat Oyunları\'nda dört altın madalya kazanarak Nazilerin ırk üstünlüğü propagandasını gölgede bırakan Amerikalı atlet kimdir?', 'Jesse Owens', ['Carl Lewis', 'Jim Thorpe', 'Joe Louis'], 'Owens 100 ve 200 metre, uzun atlama ve 4x100 metre bayrakta altın kazandı; rejim oyunları bir propaganda gösterisine dönüştürmek istemişti.'),
  ('Fransa\'nın I. Dünya Savaşı\'nda Batı Afrika sömürgelerinden topladığı ve Batı Cephesi\'nde savaştırdığı piyade birliklerine ne ad verilir?', 'Senegal Avcıları', ['Gurkha Tüfekçileri', 'Zuhaf Muhafızları', 'Askari Birlikleri'], '\'Tirailleurs sénégalais\' adı yalnız Senegallileri değil Fransız Batı Afrikası\'nın birçok halkından askerleri kapsıyordu; Gurkhalar ise İngiliz ordusundaki Nepalli askerlerdir.'),
  ('Savaş sırasında İngiltere ve Fransa\'nın cephe gerisinde lojistik işlerde çalıştırmak için anlaşmayla getirdiği yaklaşık yüz kırk bin kişilik işçi gücü hangi ülkeden gelmiştir?', 'Çin', ['Japonya', 'Brezilya', 'Meksika'], 'Çin İşçi Kolordusu limanlarda, demiryollarında ve siper kazmada çalıştı; Çin 1917\'de Almanya\'ya savaş ilan etmişti.'),
  ('Sömürgelerin ve dominyonların I. Dünya Savaşı\'na büyük insan gücü katkısı yapmasının savaş sonrası dönemde yarattığı siyasi etki nedir?', 'Özerklik ve bağımsızlık taleplerinin güçlenmesi', ['Sömürgecilere bağlılığın kalıcı olarak artması', 'Sömürge halklarının oy hakkını tümüyle yitirmesi', 'Dominyonların İngiltere\'ye vergi ödemeye başlaması'], 'Savaşta kan döken halklar daha fazla söz hakkı istedi; Hindistan\'da ulusal hareket güçlendi, Kanada ve Avustralya ise Paris\'te ayrı temsil hakkı elde etti.'),
  ('Troçki\'nin Kızıl Ordu\'yu kurarken eski çarlık subaylarını görevlendirip yanlarına siyasi komiserler atamasının amacı nedir?', 'Askerî uzmanlıktan yararlanırken bu subayların sadakatini denetim altında tutmak', ['Orduyu yalnızca seçilmiş subaylarla yönetmek', 'Eski çarlık subaylarını rütbeleriyle birlikte yeniden saraya bağlamak ve monarşiyi canlandırmak', 'Kızıl Ordu\'yu monarşiye bağlamak'], 'Profesyonel subaylara ihtiyaç vardı ama güvenilmiyorlardı; komiserler emirleri birlikte imzalayarak partinin denetimini sağladı.'),
  ('Aşağıdaki diktatörlerden hangisi iktidara ötekilerden daha önce gelmiştir?', 'Mussolini', ['Hitler', 'Franco', 'Salazar'], 'Mussolini 1922\'de, Salazar 1932\'de başbakan, Hitler 1933\'te şansölye oldu; Franco ise İç Savaş\'ı 1939\'da kazandı.'),
  ('1914\'te savaşa giren Avrupa halklarında görülen yaygın coşku ile 1918\'deki ruh hâli karşılaştırıldığında hangi değişim öne çıkar?', 'Kısa ve şanlı bir savaş beklentisinin yerini yorgunluk ve hayal kırıklığının alması', ['Coşkunun savaş uzadıkça daha da artarak 1918\'de bütün ülkelerde doruğa çıkması', 'Halkların savaşa başından sonuna kadar kayıtsız kalması', 'Savaşın yalnızca sömürgelerde hissedilmesi'], 'Pek çok kişi \'Noel\'e kadar evde olacağız\' diye düşünüyordu; uzayan siper savaşı, kayıplar ve kıtlık 1917-1918\'de grev ve isyanlara yol açtı.'),
  ('Aşağıdaki ülkelerin hangisinde kadınlar savaşlar arası dönem boyunca ulusal seçimlerde oy kullanma hakkı elde edememiştir?', 'Fransa', ['Almanya', 'Birleşik Krallık', 'ABD'], 'Almanya 1918\'de, ABD 1920\'de, Birleşik Krallık 1918\'de sınırlı, 1928\'de eşit oy hakkı tanıdı; Fransa\'da Senato\'nun direnişi nedeniyle kadınlar ancak 1944\'te oy hakkı kazandı.'),
  ('1920\'lerde kısa saçları, diz boyu etekleri ve geleneksel davranış kurallarını hiçe sayan tutumlarıyla öne çıkan genç kadınlara ABD ve Avrupa\'da verilen ad nedir?', 'Flapper', ['Süfrajet', 'Pin-up', 'Hippi'], 'Flapper\'lar savaş sonrası toplumsal değişimin ve kadınların kamusal hayattaki yeni görünürlüğünün simgesi oldu.'),
  ('Sovyet Rusya\'nın 1917-1920 arasında evlilik, boşanma ve kadın hakları alanında yaptığı düzenlemeler dönemin Avrupa\'sıyla karşılaştırıldığında nasıl değerlendirilir?', 'Boşanmayı kolaylaştırıp kürtajı yasallaştıran oldukça radikal düzenlemelerdi', ['Kadınları her türlü siyasi haktan yoksun bırakan geleneksel düzenlemelerdi', 'Avrupa\'daki düzenlemelerin tümüyle aynısıydı', 'Yalnızca kilise nikâhını geçerli sayıyordu'], 'Sovyet Rusya 1920\'de kürtajı yasallaştıran ilk ülke oldu; ancak Stalin döneminde 1936\'da kürtaj yeniden yasaklandı ve aile politikası muhafazakârlaştı.'),
  ('1919\'da Weimar\'da Walter Gropius tarafından kurulan ve sanatla zanaatı, işlevsellikle tasarımı birleştiren okul hangisidir?', 'Bauhaus', ['Wiener Werkstätte', 'Deutscher Werkbund', 'De Stijl'], 'Bauhaus, Weimar Cumhuriyeti\'nin kültürel yenilikçiliğinin simgesiydi; okul Nazi baskısıyla 1933\'te kapandı.'),
  ('İngiltere\'de BBC\'nin, sonradan kamu kuruluşuna dönüşmek üzere, ilk kez bir şirket olarak radyo yayınına başladığı yıl hangisidir?', '1922', ['1912', '1930', '1936'], 'British Broadcasting Company 1922\'de kuruldu, 1927\'de kraliyet beratıyla kamu kurumu olan British Broadcasting Corporation\'a dönüştü.'),
  ('İspanya\'da Şubat 1936 seçimlerini kazanan Halk Cephesi koalisyonunun bileşimi hangisinde doğru verilmiştir?', 'Cumhuriyetçiler, sosyalistler ve komünistlerden oluşan sol ittifak', ['Monarşistler ve Katolik muhafazakârların ittifakı', 'Faşist Falanj ile ordunun birlikte kurduğu cephe', 'Bask ve Katalan milliyetçilerinin ayrılıkçı cephesi'], 'Halk Cephesi\'nin zaferi sağı ve orduyu tedirgin etti; aynı yılın Temmuz\'unda generaller ayaklandı.'),
  ('İspanya İç Savaşı\'nda Cumhuriyetçi cephenin zayıflamasında etkili olan iç etkenlerden biri aşağıdakilerden hangisidir?', 'Anarşistler, komünistler ve sosyalistler arasındaki sert ideolojik bölünme', ['Cumhuriyet\'in Fransa\'dan sınırsız askerî yardım alması', 'Bütün ordunun Cumhuriyet\'e bağlı kalması', 'Kilisenin Cumhuriyetçileri desteklemesi'], 'Devrim mi önce, savaş mı önce tartışması Cumhuriyetçileri böldü; Mayıs 1937 Barselona çatışmaları bu bölünmenin en sert örneği oldu.'),
  ('İspanya İç Savaşı\'nın sona erdiği 1939 baharında Franco\'nun kendisi için kullandığı ve \'önder\' anlamına gelen unvan hangisidir?', 'Caudillo', ['Duce', 'Führer', 'Conducator'], 'Franco \'Tanrı\'nın lütfuyla İspanya\'nın Caudillo\'su\' unvanıyla 1975\'teki ölümüne kadar ülkeyi yönetti.'),
  ('Milletler Cemiyeti\'nin kurulmasındaki rolü nedeniyle 1919 Nobel Barış Ödülü\'ne layık görülen devlet adamı kimdir?', 'Woodrow Wilson', ['Georges Clemenceau', 'David Lloyd George', 'Léon Bourgeois'], 'Wilson ödülü 1920\'de aldı; Cemiyet\'in ilk Konsey başkanı Léon Bourgeois ise 1920 ödülünü kazandı.'),
  ('Almanya\'nın donanma yarışı Britanya ile ilişkileri nasıl etkilemiştir?', 'Britanya\'yı Almanya karşısında Fransa ve Rusya\'ya yaklaşmaya itmiştir', ['Britanya\'yı Almanya ile ittifak kurmaya ve Fransa\'dan uzaklaşmaya yöneltmiştir', 'İki ülkenin sömürgelerde ortak bir anlaşmaya ve ortak donanmaya varmasına yol açmıştır', 'Britanya\'nın kendi donanmasını küçültüp karasal orduya yönelmesini sağlamıştır'], 'Britanya adalar ve imparatorluk bağlantıları için üstün donanmaya dayandığından Alman tehdidi onu 1904 ve 1907 anlaşmalarıyla Fransa ve Rusya\'ya yakınlaştırdı.'),
  ('Savaşın başında uçakların daha çok keşif için kullanılmasının asıl nedeni nedir?', 'Düşman mevzilerini ve topçu atışlarını gözlemlemekte çok değerli olmaları', ['Silah taşıyamayacak kadar hantal ve düşük hızda olmaları nedeniyle', 'Askerlerin uçaklara güvenmemesi ve gözlem balonlarını tercih etmesi', 'Yalnızca denizaşırı seferlerde ve uzun mesafe uçuşlarda kullanılabilmeleri'], 'İlk dönemde uçaklar ordunun gözü sayıldı; bu keşif işlevi karşılıklı avcı uçaklarının doğmasına yol açtı.'),
  ('Eylül 1918\'de Bulgaristan\'ın yenilgisini kabul ettiği ve savaştan çekilen ilk Merkez Devleti olmasını sağlayan ateşkes, hangi Yunan limanının adıyla anılır?', 'Selanik', ['Belgrad', 'Sofya', 'Bükreş'], 'Bulgaristan 29 Eylül 1918\'de Selanik Ateşkesi\'ni imzalayarak savaştan çekilen ilk Merkez Devleti oldu.'),
  ('1905 Birinci Fas Krizi\'nde Kayzer II. Wilhelm\'in Tanca\'ya gitmesinin amacı neydi?', 'Fransa\'nın Fas\'taki nüfuzunu sınamak ve Britanya-Fransa yakınlaşmasını bozmak', ['Fas\'ı Almanya\'ya bağlayarak oradaki limanları donanmaya açmak', 'İspanya ile askerî ittifak kurup Fransa\'yı kuşatmak', 'Cebelitarık\'ı İngiltere\'den alarak Akdeniz\'i kontrol etmek'], 'Alman diplomasisi Fas\'ın bağımsızlığını savunarak 1904 Entente Cordiale\'i zayıflatmayı umdu; sonuçta Britanya Fransa\'ya daha çok yaklaştı.'),
  ('1917 sonbaharında İtalyan ordusunun ağır yenilgiye uğradığı ve Piave Nehri\'ne geri çekildiği muharebe hangisidir?', 'Caporetto', ['Isonzo', 'Vittorio Veneto', 'Gorizia'], 'Alman destekli Avusturya taarruzu Caporetto\'da İtalyan hatlarını yardı; çekilme İtalya\'da büyük moral çöküşü yarattı.'),
  ('Savaşan ülkelerin hükümetlerinin \'savaş tahvilleri\' satarak halktan borç toplamasının temel amacı nedir?', 'Harcamaları vergi artışına başvurmadan ve halkın desteğini alarak finanse etmek', ['Tahvil sahiplerine toprak dağıtmak', 'Ordunun maaşlarını yurt dışından ödemek', 'Parayı değersizleştirerek enflasyonu azaltmak'], 'Tahvil kampanyaları propaganda ile birleşti; devlet savaş giderini borçlanarak karşıladı ve halk savaş çabasına duygusal olarak da bağlandı.'),
  ('1937\'de Japonya\'nın Çin\'e yönelik büyük saldırısını başlatan olay, hangi köprü yakınındaki çatışmadır?', 'Marco Polo (Lugou) Köprüsü Olayı', ['Yalu Köprüsü Olayı', 'Nanjing Köprüsü Olayı', 'Mukden Köprüsü Olayı'], 'Temmuz 1937\'de Pekin yakınındaki çatışma açık Çin-Japon Savaşı\'na dönüştü; Japonlar kısa sürede Pekin ve Şanghay\'ı aldı.'),
  ('Milletler Cemiyeti\'nin İtalya\'ya uyguladığı yaptırımların etkisiz kalmasının nedeni neydi?', 'Petrol ve kömür gibi kritik maddeler yaptırım dışı bırakıldı, Süveyş Kanalı açık kaldı', ['Yaptırımlar yalnız gıda ihracatını kapsadığı için İtalya\'yı etkilememiştir', 'Yaptırımlar yalnız silah ticaretini kapsamış, İtalya\'nın silah ihracatı olmadığından etkisiz kalmıştır', 'Yaptırımlar Habeşistan tarafından reddedilmiş, Cemiyet kararları uygulatamamıştır'], 'Sınırlı yaptırımlar ve Britanya-Fransa\'nın çekingenliği Mussolini\'yi durduramadı; Hoare-Laval planı da güveni zedeledi.'),
  ('İspanyol gribine bu adın verilmesinin nedeni nedir?', 'Savaşa katılmayan İspanya\'da basının hastalığı serbestçe yazması', ['Hastalığın ilk kez Madrid\'de ortaya çıkması ve yayılması', 'Salgının İspanyol askerlerle birlikte cepheye yayılması', 'Hastalığın İspanyol sömürgelerinden Avrupa\'ya taşınması'], 'Savaşan ülkelerde sansür vardı; tarafsız İspanya\'nın haberleri hastalığı bu adla duyurdu, kaynağı ise belirsizdir.'),
  ('Ernest Hemingway\'in I. Dünya Savaşı\'nı İtalya cephesinde işleyen romanı hangisidir?', 'Silahlara Veda', ['Çanlar Kimin İçin Çalıyor', 'Güneş de Doğar', 'Yaşlı Adam ve Deniz'], 'Hemingway İtalya cephesinde ambulans sürücüsüydü; 1929\'da yayımlanan roman Frederic Henry ile hemşire Catherine Barkley\'in öyküsünü anlatır.'),
  ('\'Kayıp Kuşak\' terimi hangi topluluğu anlatır?', 'Savaş sonrasında yönünü ve inancını yitiren, genç yaşta savaşa katılmış kuşağı', ['Savaşta ölen askerlerin yetim kalmış çocuklarını', 'Savaş döneminde ülkelerini terk eden aydın ve sanatçıları', 'Savaş sırasında doğup savaş yıllarında büyüyen çocukları'], 'Gertrude Stein\'e atfedilen terim, savaş deneyimiyle hayal kırıklığına uğrayan Hemingway ve Fitzgerald gibi yazarları betimler.'),
  ('ABD\'de kadınlara oy hakkını güvence altına alan anayasa değişikliği hangi yıl onaylanmıştır?', '1920', ['1908', '1913', '1929'], '19. Değişiklik 1920\'de yürürlüğe girdi ve cinsiyete dayalı oy hakkı kısıtlamalarını yasakladı.'),
  ('Savaş sırasında kadınların fabrikalarda çalışmasının oy hakkı tartışmasına etkisi nedir?', 'Kadınların savaş çabasına katkısı oy hakkı taleplerini güçlendirmiştir', ['Kadınların siyasetten tamamen uzaklaştırılmasına yol açmıştır', 'Oy hakkı tartışmasının tamamen sona ermesini sağlamıştır', 'Yalnızca işçi sınıfından kadınlara oy hakkı verilmesine neden olmuştur'], 'Cephedeki erkeklerin yerini alan kadınlar, savaş sonrasında Britanya, Almanya ve başka ülkelerde siyasal haklar elde etti.'),
  ('Almanya\'nın 1914\'te Belçika\'nın tarafsızlığını ihlal etmesi hangi devletin savaşa girmesine yol açmıştır?', 'Britanya', ['Amerika Birleşik Devletleri', 'İtalya', 'Japonya'], 'Britanya 1839 Londra Antlaşması\'yla Belçika\'nın tarafsızlığını güvence altına almıştı; Alman işgali üzerine 4 Ağustos\'ta savaş ilan etti.'),
  ('Marne Muharebesi (1914) sonrasında Batı Cephesi\'nin niteliği nasıl değişmiştir?', 'Hareket savaşından siper savaşına geçilmiştir', ['Savaşın denizlere ve sömürgelere kaydığı yeni bir döneme geçilmiştir', 'Cephenin Belçika\'dan Fransa\'nın güneyine kaymasıyla yeni bir hat oluşmuştur', 'Almanların Paris\'i alıp savaşı kazandığı bir döneme girilmiştir'], 'Alman ilerleyişi durdurulunca iki taraf Kuzey Denizi\'nden İsviçre sınırına uzanan siper hatları kazdı.'),
  ('1916 yazında Rus ordusunun Avusturya-Macaristan\'a karşı kazandığı başarılı harekât hangi komutanın adıyla anılır?', 'Brusilov', ['Kornilov', 'Kolçak', 'Denikin'], 'Brusilov Taarruzu Avusturya ordusunu ağır yıprattı, ancak Rusya\'nın kendi kayıpları da çok büyüktü.'),
  ('Almanya\'nın savaş sonunda teslim edilen filosunun 1919\'da kendi mürettebatınca batırıldığı İskoçya\'daki körfez hangisidir?', 'Scapa Flow', ['Gibraltar', 'Jutland', 'Kiel'], 'Almanlar, filonun Müttefiklere dağıtılmasını önlemek için 21 Haziran 1919\'da gemilerini kendi elleriyle batırdı.'),
  ('1923 hiperenflasyonunda Alman toplumunda en çok zarara uğrayan kesim hangisi olmuştur?', 'Birikimlerini nakit ve tahvil olarak elinde tutan orta sınıf', ['Borçlarını değersiz parayla ödeyen sanayiciler', 'Maddi varlık sahibi büyük toprak ağaları', 'Yabancı para biriktiren ihracatçılar'], 'Tasarruflar ve emekli maaşları değer yitirirken borçlular ve maddi varlık sahipleri görece kazançlı çıktı; orta sınıfın cumhuriyete güveni sarsıldı.'),
  ('1923\'te yaşanan hiperenflasyondan sonra Almanya\'da para reformuyla çıkarılan yeni para birimi hangisidir?', 'Rentenmark', ['Papiermark', 'Goldmark', 'Taler'], 'Kasım 1923\'te çıkarılan Rentenmark, Stresemann hükümeti döneminde mali istikrarı sağladı.'),
  ('Weimar Cumhuriyeti\'nin ilk cumhurbaşkanı kimdir?', 'Friedrich Ebert', ['Paul von Hindenburg', 'Gustav Stresemann', 'Philipp Scheidemann'], 'Sosyal Demokrat Ebert, 1919\'da Ulusal Meclis tarafından seçildi ve 1925\'teki ölümüne dek görevde kaldı.'),
  ('1920\'de Berlin\'de hükümete karşı başlatılan ve genel grevle bastırılan başarısız darbe girişimi hangisidir?', 'Kapp Darbesi', ['Bira Salonu Darbesi', 'Spartakist Ayaklanması', 'Ruhr Ayaklanması'], 'Serbest birliklerin desteklediği Wolfgang Kapp\'ın girişimi, işçilerin genel grevi ve memurların destek vermemesiyle çöktü.'),
  ('Hitler\'in Bira Salonu Darbesi\'nden sonra izlediği strateji nedir?', 'Seçim ve propaganda yoluyla yasal biçimde iktidara gelmeye çalışmak', ['Orduya darbe yaptırmak', 'Siyasetten çekilip yurtdışına gitmek', 'Komünistlerle ittifak kurmak'], 'Darbenin başarısızlığı Nazileri seçim yolunu denemeye yöneltti; Büyük Buhran\'ın yarattığı kitlesel hoşnutsuzluk bu yolu açtı.'),
  ('Reichstag binasının Şubat 1933\'te yanması, Nazilerin hangi adımını kolaylaştırmıştır?', 'Komünistleri suçlayarak temel hak ve özgürlükleri askıya alan kararname çıkarmayı', ['Cumhurbaşkanlığı seçimlerini yapmayı', 'Almanya\'yı savaşa sokmayı', 'Ordunun dağıtılmasını'], 'Hükümet yangını komünistlere yükledi; \'Halkı ve Devleti Koruma Kararnamesi\' ile özgürlükler kaldırıldı ve tutuklamalar başladı.'),
  ('1934\'te Cumhurbaşkanı Hindenburg\'un ölümünün ardından Hitler hangi unvanı alarak iki makamı birleştirmiştir?', 'Führer ve Reich Şansölyesi', ['Reichstag Başkanı ve Başkomutan', 'Cumhurbaşkanı ve Başbakan', 'Kayzer ve Şansölye'], 'Ağustos 1934\'te cumhurbaşkanlığı makamı kaldırıldı ve yetkiler Hitler\'e geçti; ordu da ona kişisel bağlılık yemini etti.'),
  ('1935\'te çıkarılan ve Yahudilerin Alman vatandaşlığını kaldıran yasalara ne ad verilir?', 'Nürnberg Yasaları', ['Weimar Yasaları', 'Berlin Yasaları', 'Münih Yasaları'], 'Yasalar Yahudi ile Alman evliliğini yasakladı ve Yahudileri ikinci sınıf yurttaş konumuna indirdi.'),
  ('Sovyetlerde tarım topraklarının devletleştirilip köylülerin ortak çiftliklerde toplanmasına ne ad verilir?', 'Kollektivizasyon', ['Kolonizasyon', 'Reform', 'Mülksüzleştirme'], 'Zorunlu kollektivizasyon ve kulakların sürülmesi, 1932-1933\'te Ukrayna\'da büyük kıtlığa yol açtı.'),
  ('Lenin\'in \'Nisan Tezleri\'nde öne sürdüğü başlıca slogan hangisidir?', 'Barış, toprak ve ekmek', ['Vatan ya da ölüm', 'Tüm iktidar Çar\'a', 'Sanayi için ekmek'], 'Lenin, Geçici Hükümet\'e destek verilmemesini ve \'Bütün iktidar Sovyetlere\' çağrısını yaptı; halkın üç temel isteğini slogan haline getirdi.'),
  ('Büyük Buhran\'ın sanayileşmiş ülkelerdeki en belirgin toplumsal sonucu nedir?', 'Kitlesel işsizlik ve yoksulluk', ['Kırsal nüfusun hızla artması ve tarımın genişlemesi', 'Ücretlerin hızla yükselmesi ve emek kıtlığı', 'Doğum oranlarının sıçraması ve nüfus patlaması'], 'ABD\'de işsizlik yaklaşık dörtte bire, Almanya\'da altı milyonun üzerine çıktı; bu durum aşırı akımların güçlenmesine zemin hazırladı.'),
  ('1920\'lerde ABD\'de caz müziğinin yaygınlaşması hangi toplumsal olguyla birlikte anılır?', 'Siyah nüfusun kuzey kentlerine göçü ve Harlem Rönesansı', ['Köle ticaretinin yeniden başlaması ve güney plantasyonlarının büyümesi', 'Güney eyaletlerin Birlik\'ten ayrılma kararı alması', 'Avrupa\'dan gelen göçün hızlanması ve kentlerin büyümesi'], 'Büyük Göç\'le kuzeye giden siyahlar Harlem\'de edebiyat, müzik ve sanatta yeni bir kültürel atılım yarattı.'),
  ('1926\'da İngiltere\'de madencilerin başlattığı ve diğer sektörlere yayılan büyük eylem hangisidir?', 'Genel Grev', ['Luddit İsyanı', 'Peterloo Olayı', 'Chartist Hareketi'], 'Maden ücretlerindeki kesintiye tepki olarak başlayan grev dokuz gün sürdü ve hükümetin sert tavrıyla başarısız oldu.'),
  ('Alman Condor Lejyonu\'nun 1937\'de bombaladığı ve Picasso\'nun ünlü tablosuna konu olan Bask kenti hangisidir?', 'Guernica', ['Barselona', 'Bilbao', 'Toledo'], 'Guernica bombardımanı sivil nüfusa karşı hava saldırısının sembolü oldu.'),
  ('1932\'de ABD\'de Birinci Dünya Savaşı gazilerinin ödenmemiş ikramiyelerini istemek için Washington\'a yürüyen topluluk hangi adla bilinir?', 'Bonus Ordusu', ['Kızıl Yürüyüş Hareketi', 'Açlık Yürüyüşçüleri Birliği', 'Gaziler Sendikası Cephesi'], 'Binlerce gazi Kongre\'den ikramiyeleri için baskı yaptı; Hoover yönetimi ordu birlikleriyle kampları dağıttı ve bu olay Hoover\'ın itibarını sarstı.'),
  ('1927\'de Fritz Lang\'ın çektiği ve Weimar dönemi Alman sinemasının Dışavurumculuk akımındaki örneklerinden sayılan bilimkurgu filmi hangisidir?', 'Metropolis', ['Nosferatu', 'Kabine', 'Mabuse'], 'Metropolis, sınıf ayrılığı ve makineleşme temalarıyla Weimar kültürünün yaratıcı çeşitliliğinin simgesidir.'),
  ('1921-1922 Washington Deniz Konferansı\'nda büyük devletlerin ağır gemi tonajlarını oranlamasının amacı nedir?', 'Donanma silahlanma yarışını sınırlamak ve savaş maliyetlerini azaltmak', ['Almanya\'yı silahlandırarak Doğu tehdidine karşı kullanmak', 'Japonya\'yı donanma yarışından tamamen dışlamak', 'Milletler Cemiyeti\'nin donanmasını güçlendirmek'], 'ABD, Britanya, Japonya, Fransa ve İtalya savaş gemisi tonajlarını belirli oranlarda sınırlamayı kabul etti; ABD ve Britanya\'ya karşılık Japonya daha az orana razı oldu.'),
  ('Milletler Cemiyeti\'nin kararlarında oybirliği ilkesi aranması, kuruluşun hangi zayıflığına yol açmıştır?', 'Karar almanın zorlaşmasına ve tek bir devletin vetosuyla işlemlerin tıkanmasına', ['Cemiyet\'in kendi silahlı ordusunun bulunmasına ve hızlı müdahaleye', 'Üyelerin kararları çok hızlı alıp hemen uygulamasına', 'Başkanlığın her yıl el değiştirmesi nedeniyle sürekliliğin kopmasına'], 'Oybirliği kuralı ve zorlayıcı güç eksikliği Cemiyet\'in saldırgan devletler karşısında etkisizliğini artırdı.'),
  ('Mussolini\'nin \'Il Duce\' unvanını benimsemesi, rejimin hangi özelliğini yansıtır?', 'Tek önder etrafında toplanan kişilik kültünü', ['Çok partili parlamenter demokrasiyi ve muhalefetin korunmasını', 'Krallığın kaldırılıp cumhuriyetin ilan edilmesini', 'Federal yapıya dayalı bölgesel özerkliği'], 'Unvan \'önder\' anlamına gelir; propaganda, medya ve gösterilerle kişi kültü kuruldu.'),
  ('Şu olayları eskiden yeniye sıralayınız: Münih Konferansı, Kapp Darbesi, Roma Yürüyüşü. Hangi sıra doğrudur?', 'Kapp Darbesi, Roma Yürüyüşü, Münih Konferansı', ['Roma Yürüyüşü, Münih Konferansı, Kapp Darbesi', 'Münih Konferansı, Roma Yürüyüşü, Kapp Darbesi', 'Kapp Darbesi, Münih Konferansı, Roma Yürüyüşü'], 'Kapp Darbesi 1920, Roma Yürüyüşü 1922, Münih Konferansı 1938\'de gerçekleşti.'),
  ('I. Dünya Savaşı boyunca Avrupa\'da tarafsız kalmayı başaran ülkelerden biri hangisidir?', 'İsviçre', ['Belçika', 'Romanya', 'Bulgaristan'], 'İsviçre, İsveç, İspanya, Hollanda ve Danimarka savaşa girmedi; Belçika ise Alman işgaline uğradı.'),
];
